// GENERADO por backend/herramientas/generar_aprende.py a partir de backend/retos/conceptos/css.py. No lo edites a mano: cambia los conceptos y vuelve a generarlo.
// m = etapa · t = título · x = qué es · u = para qué sirve · p = puntos clave · c = código · h = qué hace · r = ahora tú · e = error común
export default [
  {"m": "Qué es CSS", "t": "Qué es CSS", "x": "Lenguaje que da estilo y aspecto a las páginas web.\n\nCSS significa Cascading Style Sheets (hojas de estilo en cascada). HTML dice qué hay en la página y CSS dice cómo se ve. Con unas pocas líneas puedes cambiar toda la apariencia de un sitio.", "u": "Cambiar colores, tamaños y posición de lo escrito en HTML.\n\nQuieres cambiar el color y el tamaño de los textos de tu página sin tocar su contenido.", "p": ["CSS da estilo a las páginas web.", "CSS significa Cascading Style Sheets.", "HTML dice qué hay y CSS dice cómo se ve."], "c": "<style>\n  /* CSS: cómo se ve */\n  h1 { color: tomato; }\n</style>\n<!-- HTML: qué hay -->\n<h1>Hola, CSS</h1>", "h": "Pinta de rojo un título que escribió HTML.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: CSS significa Cascading Style ___. (una palabra)", "e": "Intentar dar color a la página usando solo HTML."},
  {"m": "Qué es CSS", "t": "Separar estructura y estilo", "x": "Idea de escribir el contenido en HTML y el aspecto en CSS.\n\nSi el color de los títulos está escrito en cada etiqueta, cambiarlo exige tocar cientos de líneas. Con CSS cambias una sola regla y toda la web se actualiza. Es la razón de ser de las hojas de estilo.", "u": "Cambiar el diseño sin reescribir el contenido.\n\nQuieres cambiar el color de todos los títulos del sitio modificando un solo sitio.", "p": ["Separar contenido y estilo permite cambiar el diseño en un solo lugar.", "El contenido vive en HTML y el aspecto en CSS.", "Una regla CSS puede afectar a cientos de elementos."], "c": "<style>\n  /* Una regla cambia TODOS los títulos de la página */\n  h2 { color: seagreen; }\n</style>\n<h2>Primer título</h2>\n<h2>Segundo título</h2>\n<h2>Tercer título</h2>", "h": "Cambia el color de tres títulos con una sola regla.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El contenido se escribe en HTML y el aspecto en ___. (3 letras)", "e": "Escribir el estilo repetido en cada etiqueta."},
  {"m": "Qué es CSS", "t": "CSS en línea", "x": "Estilo escrito con el atributo style en una etiqueta.\n\nSe escribe así: <p style=\"color: red;\">. Es rápido, pero mezcla estructura y estilo y no se puede reutilizar. Úsalo solo para pruebas o casos muy puntuales.", "u": "Dar un estilo rápido a un único elemento.\n\nQuieres probar un color rápido en un único párrafo escribiéndolo dentro de su etiqueta.", "p": ["El CSS en línea se escribe en el atributo style.", "El CSS en línea afecta solo a ese elemento.", "El CSS en línea mezcla estructura y estilo."], "c": "<!-- style en la propia etiqueta: afecta solo a este párrafo -->\n<p style=\"color: crimson; font-size: 22px;\">Texto con CSS en línea</p>\n<p>Este párrafo no cambia.</p>", "h": "Da estilo solo al primer párrafo desde su propia etiqueta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El CSS en línea se escribe en el atributo ___. (5 letras)", "e": "Usar CSS en línea para todo el sitio."},
  {"m": "Qué es CSS", "t": "CSS interno", "x": "Estilos escritos en una etiqueta style dentro de la página.\n\nSe escribe una etiqueta <style> en el head con reglas dentro. Sirve para toda esa página, pero no se comparte con otras. Es cómodo para pruebas y ejemplos, como los de CódigoCamp.", "u": "Dar estilos a una sola página sin archivos extra.\n\nQuieres dar estilo a toda una página desde el mismo archivo HTML.", "p": ["El CSS interno va dentro de una etiqueta style.", "El CSS interno afecta a toda esa página.", "El CSS interno no se comparte entre páginas distintas."], "c": "<head>\n  <!-- style en el head: afecta a toda esta página -->\n  <style>\n    p { color: navy; }\n  </style>\n</head>\n<body><p>Uno</p><p>Dos</p></body>", "h": "Pinta de azul todos los párrafos de la página con una etiqueta style.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El CSS interno se escribe dentro de la etiqueta ___. (5 letras)", "e": "Repetir el mismo bloque style en cada página."},
  {"m": "Qué es CSS", "t": "CSS externo", "x": "Estilos guardados en un archivo .css aparte.\n\nLos estilos se guardan en un archivo como estilos.css y se enlazan en el head con <link rel=\"stylesheet\" href=\"estilos.css\">. Es la forma recomendada, porque todas las páginas comparten el mismo archivo y se mantiene limpio.", "u": "Compartir los mismos estilos entre muchas páginas.\n\nQuieres que cinco páginas compartan los mismos estilos desde un único archivo.", "p": ["El CSS externo se guarda en un archivo con extensión .css.", "Se conecta con link rel=\"stylesheet\" en el head.", "Es la forma recomendada de aplicar estilos."], "c": "<head>\n  <!-- conecta el archivo estilos.css con esta página -->\n  <link rel=\"stylesheet\" href=\"estilos.css\">\n</head>\n<!-- Dentro de estilos.css habría reglas como:  p { color: teal; } -->", "h": "Conecta un archivo externo de estilos desde el head.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un archivo de estilos termina en ___. (4 caracteres)", "e": "Olvidar la ruta correcta del archivo .css. Para enlazar un archivo externo se usa la etiqueta link, no style."},
  {"m": "Qué es CSS", "t": "Regla CSS", "x": "Bloque completo con un selector y sus declaraciones.\n\nUna regla se escribe así: selector { propiedad: valor; }. El selector elige a qué elementos se aplica y entre llaves van las declaraciones. Un archivo CSS es simplemente una lista de reglas.", "u": "Decir qué elementos cambian y cómo.\n\nEscribes «p { color: red; }».", "p": ["Una regla CSS tiene un selector y llaves con declaraciones.", "Las declaraciones van entre llaves { }.", "Un archivo CSS es una lista de reglas."], "c": "<style>\n  /* selector { declaraciones } = una regla */\n  p {\n    color: purple;\n    font-size: 20px;\n  }\n</style>\n<p>Mira cómo cambia</p>", "h": "Define una regla que pinta de morado un párrafo y agranda su letra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las declaraciones de una regla se escriben entre ___. (llaves, con { })", "e": "Olvidar cerrar la llave de la regla. Falta cerrar la llave de la regla de p antes de empezar la siguiente."},
  {"m": "Qué es CSS", "t": "Selector", "x": "Parte de la regla que elige a qué elementos se aplica.\n\nEl selector más sencillo es el nombre de una etiqueta (p, h1). También hay selectores de clase (.aviso) y de id (#menu). Un selector puede elegir uno o muchos elementos a la vez.", "u": "Escoger los elementos que van a cambiar.\n\nQuieres elegir todos los títulos h2 para darles estilo.", "p": ["El selector elige los elementos que reciben el estilo.", "Un selector puede ser el nombre de una etiqueta.", "Un selector puede elegir muchos elementos a la vez."], "c": "<style>\n  /* h2 es el selector: elige todos los h2 */\n  h2 { color: darkorange; }\n</style>\n<h2>Uno</h2>\n<h2>Dos</h2>\n<p>Este no cambia</p>", "h": "Elige todos los h2 para pintarlos, dejando el p sin cambios.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En la regla «h2 { color: red; }», h2 es el ___. (8 letras)", "e": "Escribir mal el nombre de la etiqueta del selector."},
  {"m": "Qué es CSS", "t": "Propiedad y valor", "x": "Par que dice qué se cambia y a qué.\n\nLa propiedad es lo que cambias (color, font-size) y el valor es el nuevo ajuste (red, 20px). Se escriben separados por dos puntos, y la declaración termina con punto y coma.", "u": "Definir cada detalle del estilo de un elemento.\n\nEn «color: red», quieres nombrar la parte «red».", "p": ["La propiedad indica qué característica se cambia.", "El valor indica cómo queda esa característica.", "Propiedad y valor se separan con dos puntos."], "c": "<style>\n  p {\n    /* propiedad: valor; */\n    color: seagreen;\n    font-size: 24px;\n  }\n</style>\n<p>Propiedad y valor en acción</p>", "h": "Cambia dos propiedades del párrafo con sus valores.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En «color: red;», «red» es el ___. (5 letras)", "e": "Olvidar los dos puntos entre propiedad y valor. Falta el signo : entre la propiedad color y el valor red."},
  {"m": "Qué es CSS", "t": "Declaración", "x": "Una propiedad con su valor terminada en punto y coma.\n\nCada declaración termina en punto y coma. Puedes escribir las que quieras dentro de una regla, una por línea. Olvidar el punto y coma es de los errores más comunes: rompe esa línea y la siguiente.", "u": "Añadir un ajuste de estilo concreto.\n\nQuieres añadir un ajuste más, como el tamaño de la letra, dentro de una regla ya escrita.", "p": ["Una declaración termina con punto y coma.", "Una regla puede contener muchas declaraciones.", "Olvidar el punto y coma rompe la declaración siguiente."], "c": "<style>\n  h1 {\n    color: royalblue;       /* 1.ª declaración */\n    text-align: center;     /* 2.ª declaración */\n    font-size: 40px;        /* 3.ª declaración */\n  }\n</style>\n<h1>Tres declaraciones</h1>", "h": "Aplica tres declaraciones seguidas al título.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Cada declaración termina con ___. (punto y coma)", "e": "Olvidar el punto y coma al final de la línea. Falta el punto y coma al final de color: red."},
  {"m": "Qué es CSS", "t": "Comentarios CSS", "x": "Notas entre /* y */ que el navegador ignora.\n\nUn comentario CSS empieza con /* y termina con */, y puede ocupar varias líneas. Es distinto del comentario de HTML (<!-- -->). Sirve para explicar reglas o para desactivar temporalmente una línea al probar.", "u": "Explicar o desactivar partes del CSS.\n\nQuieres dejar una nota en tu hoja de estilos que el navegador ignore.", "p": ["Los comentarios CSS empiezan con /* y terminan con */.", "El navegador ignora los comentarios CSS.", "Los comentarios CSS no son iguales a los de HTML."], "c": "<style>\n  /* Este comentario explica la regla de abajo */\n  p { color: teal; }\n  /* font-size: 40px;  <- línea desactivada por ahora */\n</style>\n<p>Los comentarios no se ven</p>", "h": "Deja una nota y una línea desactivada que el navegador ignora.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un comentario CSS termina con ___. (2 caracteres)", "e": "Usar <!-- --> para comentar dentro del CSS."},
  {"m": "Qué es CSS", "t": "Cascada", "x": "Regla que decide cuál estilo gana cuando hay varios.\n\nSi dos reglas dan colores distintos al mismo elemento, gana la más específica, y si tienen igual fuerza, gana la que se escribió después. Por eso la C de CSS es de «cascading»: los estilos caen en orden.", "u": "Resolver contradicciones entre reglas.\n\nDos reglas con la misma fuerza dan colores distintos al mismo párrafo.", "p": ["Si hay empate de fuerza, gana la regla escrita al final.", "La cascada decide qué regla se aplica en un conflicto.", "El orden de las reglas importa en CSS."], "c": "<style>\n  p { color: red; }\n  /* Se escribe después con igual fuerza: gana la última */\n  p { color: blue; }\n</style>\n<p>¿De qué color me ves?</p>", "h": "Muestra que la última de dos reglas iguales es la que se aplica.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Con igual fuerza, gana la regla escrita al ___. (5 letras: final o inicio)", "e": "Cambiar una regla y no ver efecto porque otra posterior la anula."},
  {"m": "Qué es CSS", "t": "Herencia", "x": "Mecanismo por el que los hijos reciben estilos del padre.\n\nAlgunas propiedades, como color o font-family, pasan de un elemento a sus hijos. Si pones color en body, casi todo el texto lo tomará. Otras propiedades, como borde o margen, no se heredan.", "u": "Aplicar un estilo a muchos elementos desde el contenedor.\n\nQuieres que el color puesto en el body llegue a todos los textos de la página sin repetirlo.", "p": ["Los elementos hijos heredan algunas propiedades del padre.", "El color y la fuente se heredan.", "Los bordes y márgenes no se heredan."], "c": "<style>\n  /* color se hereda: lo reciben los hijos del div */\n  div { color: darkgreen; border: 2px solid darkgreen; }\n</style>\n<div>\n  Texto del padre\n  <p>Texto del hijo (hereda el color, pero no el borde)</p>\n</div>", "h": "Muestra que el hijo hereda el color pero no el borde.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El color de texto se ___ de padres a hijos. (una palabra)", "e": "Esperar que el borde del padre pase a los hijos."},
  {"m": "Qué es CSS", "t": "Especificidad", "x": "Peso que tiene cada selector al competir.\n\nUn selector de id pesa más que uno de clase, y uno de clase pesa más que uno de etiqueta: #menu gana a .menu y este gana a div. El estilo en línea pesa aún más. Entenderlo evita tener que usar !important.", "u": "Saber qué regla se impone cuando hay conflicto.\n\nUna regla de clase y otra de etiqueta chocan sobre el color de un mismo elemento.", "p": ["Un selector de id tiene más peso que uno de clase.", "Un selector de clase tiene más peso que uno de etiqueta.", "El estilo en línea pesa más que los selectores."], "c": "<style>\n  p { color: red; }          /* etiqueta: peso bajo */\n  .aviso { color: green; }   /* clase: peso medio */\n</style>\n<!-- gana .aviso aunque p esté escrita antes -->\n<p class=\"aviso\">Este texto es verde</p>", "h": "Demuestra que la regla de clase gana a la de etiqueta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Pesa más un selector de ___ que uno de clase. (2 letras)", "e": "Usar !important para resolver cualquier conflicto."},
  {"m": "Qué es CSS", "t": "Estilos por defecto", "x": "Aspecto que el navegador da a las etiquetas sin CSS.\n\nEl navegador tiene su propia hoja de estilos: los h1 salen grandes y en negrita, los enlaces azules y subrayados. Tus reglas sobrescriben estos valores. Algunos desarrolladores usan un «reset» para empezar desde cero.", "u": "Entender por qué una página sin CSS ya tiene formato.\n\nNotas que un título sin CSS ya sale grande y en negrita.", "p": ["Cada navegador aplica estilos por defecto a las etiquetas.", "Tus reglas sobrescriben los estilos por defecto.", "Un reset parte de cero para evitar diferencias entre navegadores."], "c": "<style>\n  /* Sin esta regla el enlace sería azul y subrayado por defecto */\n  a { color: inherit; text-decoration: none; }\n</style>\n<h1>Un h1 ya sale grande por defecto</h1>\n<a href=\"#\">Enlace sin su estilo original</a>", "h": "Quita el color y el subrayado que el navegador pone por defecto a los enlaces.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un enlace sin CSS se ve ___ y subrayado. (una palabra: color)", "e": "Creer que la página sin CSS no tiene ningún estilo."},
  {"m": "Qué es CSS", "t": "Estilos con el inspector", "x": "Panel del navegador que muestra y edita el CSS de un elemento.\n\nCon clic derecho e Inspeccionar ves qué reglas afectan a un elemento, cuáles se tacharon por perder en la cascada y puedes cambiar valores al instante. Los cambios son temporales: al recargar desaparecen.", "u": "Probar y entender estilos en una página en vivo.\n\nQuieres ver por qué un párrafo no cambia de color y probar valores sin guardar nada.", "p": ["El inspector muestra las reglas CSS de cada elemento.", "Las reglas que pierden en la cascada aparecen tachadas.", "Los cambios hechos en el inspector son temporales."], "c": "<style>\n  /* Abre el inspector (F12) sobre este texto y cambia el color */\n  p { color: slateblue; font-size: 24px; }\n</style>\n<p>Inspecciona este párrafo con F12</p>", "h": "Deja un párrafo para practicar con el inspector y cambiar sus estilos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El inspector se abre con la tecla ___. (3 caracteres)", "e": "Creer que los cambios del inspector se guardan."},
  {"m": "Qué es CSS", "t": "Unidades de medida", "x": "Tipos de medida usados en CSS para tamaños.\n\npx es un tamaño fijo en píxeles. % depende del elemento padre, em y rem dependen del tamaño de la letra, y vw y vh dependen del tamaño de la ventana. Cada una sirve para algo distinto; las irás usando en las siguientes etapas.", "u": "Elegir tamaños fijos o flexibles.\n\nQuieres que un tamaño dependa de la ventana del navegador y no sea fijo.", "p": ["El px es una unidad fija en píxeles.", "El % depende del tamaño del elemento padre.", "Las unidades vw y vh dependen del tamaño de la ventana."], "c": "<style>\n  /* px: fijo   %: depende del padre   vw: ancho de la ventana */\n  .a { width: 200px; background: lightblue; }\n  .b { width: 50%;   background: lightgreen; }\n  .c { width: 30vw;  background: khaki; }\n</style>\n<div class=\"a\">px</div><div class=\"b\">%</div><div class=\"c\">vw</div>", "h": "Compara tres cajas con unidades fija, relativa al padre y relativa a la ventana.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La unidad que depende del ancho de la ventana se escribe ___. (2 letras)", "e": "Usar solo px para todo y perder flexibilidad."},
  {"m": "Qué es CSS", "t": "Colores en CSS", "x": "Formas de escribir un color: nombre, hexadecimal, rgb y hsl.\n\nHay nombres como tomato, códigos hexadecimales como #ff6347, rgb(255, 99, 71) y hsl(9, 100%, 64%). Todas representan colores; el hexadecimal es el más habitual en diseño.", "u": "Dar a cada elemento el color exacto que quieres.\n\nUn diseñador te da un código de color como #ff6347.", "p": ["Un color puede escribirse como nombre, hexadecimal, rgb o hsl.", "Un color hexadecimal empieza con #.", "Hay unos 140 colores con nombre en CSS."], "c": "<style>\n  /* Los cuatro dan casi el mismo tono */\n  .a { background: tomato; }\n  .b { background: #ff6347; }\n  .c { background: rgb(255, 99, 71); }\n  .d { background: hsl(9, 100%, 64%); }\n</style>\n<p class=\"a\">nombre</p><p class=\"b\">hex</p><p class=\"c\">rgb</p><p class=\"d\">hsl</p>", "h": "Pinta cuatro párrafos con el mismo color escrito de cuatro maneras.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un color hexadecimal empieza con el símbolo ___. (un carácter)", "e": "Olvidar el # de un color hexadecimal. Un color hexadecimal debe empezar con #: #ff6347."},
  {"m": "Qué es CSS", "t": "Compatibilidad", "x": "Comprobar si un navegador admite una función de CSS.\n\nNo todos los navegadores admiten al mismo tiempo las propiedades más nuevas. El sitio caniuse.com muestra qué navegadores soportan cada función. Si el navegador no entiende una propiedad, simplemente la ignora y sigue con la siguiente.", "u": "Evitar que una propiedad nueva falle en algunos usuarios.\n\nQuieres saber si una propiedad nueva funciona en Safari antes de usarla.", "p": ["Un navegador ignora las propiedades CSS que no entiende.", "El sitio caniuse.com muestra la compatibilidad de cada función.", "Conviene probar el CSS en más de un navegador."], "c": "<style>\n  /* Primero un valor que todos entienden; después el moderno */\n  .caja {\n    background: gray;\n    background: linear-gradient(red, orange);\n  }\n</style>\n<div class=\"caja\" style=\"height:60px\">Respaldo para navegadores antiguos</div>", "h": "Deja un color de respaldo antes de un degradado moderno.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El sitio para comprobar la compatibilidad de CSS se llama can I ___. (3 letras)", "e": "Usar una función nueva sin comprobar si funciona en todos."},
  {"m": "Qué es CSS", "t": "Nombres de clases", "x": "Forma ordenada de nombrar las clases de CSS.\n\nUsa minúsculas, guiones y nombres que describan función, no aspecto: .boton-principal en lugar de .azul-grande. Así, si el botón cambia de azul a verde, el nombre sigue teniendo sentido.", "u": "Escribir clases que se entiendan y se puedan reutilizar.\n\nQuieres un nombre de clase que siga valiendo aunque cambie el color del botón.", "p": ["Los nombres de clase se escriben en minúsculas con guiones.", "Un buen nombre describe la función, no el color.", "Evita espacios y tildes en los nombres de clase."], "c": "<style>\n  /* Mal: describe el aspecto */\n  .azul-grande { background: dodgerblue; }\n  /* Bien: describe la función */\n  .boton-principal { background: dodgerblue; color: white; padding: 8px 16px; }\n</style>\n<button class=\"boton-principal\">Comprar</button>", "h": "Compara un nombre de clase por aspecto con otro por función.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una clase se escribe en el CSS con un ___ delante. (punto)", "e": "Nombrar una clase por su color y luego cambiar el color."},
  {"m": "Qué es CSS", "t": "Cómo practicar CSS", "x": "Costumbre de experimentar con estilos cambiando valores.\n\nCSS se aprende cambiando valores y viendo qué pasa. Prueba un color, un tamaño, rompe algo a propósito. Reproduce diseños de sitios que te gusten e inspecciónalos. Diez minutos al día valen más que una tarde entera.", "u": "Entender CSS probando y viendo el resultado al instante.\n\nQuieres aprender CSS de forma rápida y sin frustrarte.", "p": ["CSS se aprende cambiando valores y observando el resultado.", "Reproducir diseños que te gustan es una gran práctica.", "Practicar poco cada día es mejor que mucho de golpe."], "c": "<style>\n  /* Reto: cambia los colores, el tamaño y el borde, y mira qué pasa */\n  .tarjeta {\n    background: #fef3c7;\n    border: 3px dashed #f59e0b;\n    padding: 16px;\n    border-radius: 12px;\n  }\n</style>\n<div class=\"tarjeta\">Mi primera tarjeta con estilo propio</div>", "h": "Ofrece una tarjeta para practicar cambiando colores, borde y esquinas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: CSS se aprende cambiando ___ y mirando el resultado. (una palabra)", "e": "Leer sobre CSS sin escribir nunca estilos."},
  {"m": "Selectores, texto y color", "t": "Selector de clase", "x": "Selector con punto que elige elementos con esa clase.\n\nSe escribe .nombre en CSS y class=\"nombre\" en HTML. Varios elementos pueden compartir clase, y un elemento puede tener varias. Es el selector más usado porque es reutilizable.", "u": "Dar el mismo estilo a elementos distintos.\n\nQuieres dar el mismo fondo amarillo a un párrafo y a un div distintos.", "p": ["El selector de clase empieza con un punto.", "Varios elementos pueden compartir la misma clase.", "Un elemento puede tener varias clases a la vez."], "c": "<style>\n  /* el punto indica que es una clase */\n  .aviso { background: #fef08a; padding: 8px; border-radius: 6px; }\n</style>\n<p class=\"aviso\">Párrafo con aviso</p>\n<div class=\"aviso\">Div con aviso</div>\n<p>Sin aviso</p>", "h": "Da el mismo fondo amarillo a un párrafo y a un div usando una clase.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una clase se escribe en CSS con un ___ delante. (punto)", "e": "Olvidar el punto delante del nombre de la clase. Falta el punto: para una clase se escribe .aviso, no aviso."},
  {"m": "Selectores, texto y color", "t": "Selector de id", "x": "Selector con almohadilla que elige un elemento único.\n\nSe escribe #nombre en CSS y id=\"nombre\" en HTML. Como cada id es único, el selector elige un solo elemento. Tiene más peso que una clase, así que conviene usarlo poco.", "u": "Dar estilo a un elemento concreto de la página.\n\nQuieres dar estilo solo a la cabecera principal, que existe una única vez.", "p": ["El selector de id empieza con el símbolo #.", "Un id debe aparecer solo una vez en la página.", "El selector de id pesa más que el de clase."], "c": "<style>\n  /* # indica que es un id: elige un solo elemento */\n  #principal { color: white; background: navy; padding: 12px; }\n</style>\n<h1 id=\"principal\">Título único</h1>\n<h1>Otro título normal</h1>", "h": "Pinta solo el título con id principal con fondo azul oscuro.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un id se escribe en CSS con el símbolo ___ delante. (un carácter)", "e": "Usar el mismo id en varios elementos."},
  {"m": "Selectores, texto y color", "t": "Selector universal", "x": "Selector asterisco que elige todos los elementos.\n\nEl asterisco * elige absolutamente todo. Es habitual en los «resets» para quitar márgenes y rellenos por defecto. Úsalo con cuidado: afecta a todo y puede ser más lento en páginas enormes.", "u": "Aplicar un estilo base a toda la página.\n\nQuieres quitar los márgenes por defecto de todos los elementos a la vez.", "p": ["El selector universal se escribe con un asterisco.", "El selector universal elige todos los elementos.", "Es habitual usarlo para resetear márgenes."], "c": "<style>\n  /* * elige TODOS los elementos */\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  h1 { background: gold; }\n</style>\n<h1>Sin márgenes por defecto</h1>\n<p>Todo queda pegado al borde</p>", "h": "Quita márgenes y rellenos de todos los elementos con un solo selector.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El selector universal se escribe con el símbolo ___. (un carácter)", "e": "Usar * para dar colores y afectar a toda la página sin querer."},
  {"m": "Selectores, texto y color", "t": "Agrupar selectores", "x": "Varios selectores separados por comas que comparten reglas.\n\nSi h1, h2 y h3 deben ser del mismo color, escribe h1, h2, h3 { color: navy; }. Las comas significan «y». Olvidar una coma cambia el significado de la regla.", "u": "Evitar repetir el mismo estilo en varias reglas.\n\nQuieres que h1, h2 y h3 compartan el mismo color sin escribir tres reglas.", "p": ["Los selectores agrupados se separan con comas.", "Agrupar evita repetir las mismas declaraciones.", "La coma entre selectores significa «y»."], "c": "<style>\n  /* las comas agrupan: vale para h1, h2 y h3 */\n  h1, h2, h3 { color: darkcyan; font-family: Georgia, serif; }\n</style>\n<h1>Título</h1><h2>Subtítulo</h2><h3>Apartado</h3>", "h": "Da la misma fuente y color a tres niveles de título con una sola regla.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los selectores agrupados se separan con ___. (una coma)", "e": "Olvidar la coma entre selectores agrupados."},
  {"m": "Selectores, texto y color", "t": "Selector descendiente", "x": "Selector con espacio que elige elementos dentro de otros.\n\nSe escribe con un espacio entre selectores: nav a elige los enlaces que están dentro de un nav, a cualquier nivel. Así puedes dar estilo distinto a los enlaces del menú y a los del texto.", "u": "Dar estilo solo a los elementos que están dentro de un contenedor.\n\nQuieres colorear solo los enlaces que están dentro del menú nav.", "p": ["El selector descendiente se escribe con un espacio.", "Elige elementos dentro de otro, a cualquier profundidad.", "Permite estilos distintos según el contenedor."], "c": "<style>\n  /* el espacio: enlaces DENTRO de nav */\n  nav a { color: crimson; font-weight: bold; }\n</style>\n<nav><a href=\"#\">Inicio</a> <a href=\"#\">Cursos</a></nav>\n<p>Un <a href=\"#\">enlace del texto</a> no cambia</p>", "h": "Pinta de rojo solo los enlaces del menú, no los del texto.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En «nav a», el selector elige los enlaces ___ de nav. (una palabra)", "e": "Poner coma en lugar de espacio y cambiar el significado."},
  {"m": "Selectores, texto y color", "t": "Selector hijo directo", "x": "Selector con > que elige solo los hijos inmediatos.\n\nul > li elige solo los li que son hijos directos de ul, no los que están dentro de sublistas. El símbolo > evita que el estilo se filtre a niveles más profundos.", "u": "Ser más preciso que con el selector descendiente.\n\nQuieres estilar solo los li del primer nivel de una lista, no los de sublistas.", "p": ["El selector hijo usa el símbolo >.", "Elige solo hijos inmediatos del elemento.", "No afecta a los nietos ni a niveles más profundos."], "c": "<style>\n  /* > : solo hijos directos */\n  ul > li { color: darkred; }\n</style>\n<ul>\n  <li>Nivel 1\n    <ul><li>Nivel 2 (no cambia)</li></ul>\n  </li>\n</ul>", "h": "Pinta solo los elementos del primer nivel de la lista.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El símbolo del selector de hijo directo es ___. (un carácter)", "e": "Usar > esperando que llegue a todos los niveles."},
  {"m": "Selectores, texto y color", "t": "Selector de hermano", "x": "Selector con + que elige el elemento que sigue justo después.\n\nh2 + p elige el párrafo que va justo después de un h2 y que comparte padre con él. Es útil para destacar el primer párrafo tras un título. Existe también ~, que elige todos los hermanos siguientes.", "u": "Estilar el elemento que va inmediatamente tras otro.\n\nQuieres destacar solo el párrafo que va justo después de cada título h2.", "p": ["El selector + elige el hermano inmediato siguiente.", "Los dos elementos deben compartir el mismo padre.", "El selector ~ elige todos los hermanos siguientes."], "c": "<style>\n  /* + : el p que viene justo después de un h2 */\n  h2 + p { font-size: 20px; font-style: italic; }\n</style>\n<h2>Título</h2>\n<p>Este párrafo se destaca</p>\n<p>Este no</p>", "h": "Destaca solo el primer párrafo que sigue a un título.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El símbolo del selector de hermano adyacente es ___. (un carácter)", "e": "Esperar que + afecte a todos los párrafos siguientes."},
  {"m": "Selectores, texto y color", "t": "Selectores de atributo", "x": "Selectores entre corchetes que eligen según un atributo.\n\na[target=\"_blank\"] elige los enlaces con ese atributo. input[type=\"email\"] elige solo los campos de correo. También puedes usar [href^=\"https\"] (empieza por) o [href$=\".pdf\"] (termina en).", "u": "Estilar elementos por su atributo sin añadir clases.\n\nQuieres estilar solo los enlaces que apuntan a archivos PDF.", "p": ["Los selectores de atributo se escriben entre corchetes.", "Permiten elegir elementos según el valor de un atributo.", "Con ^= se elige lo que empieza por un texto."], "c": "<style>\n  /* [atributo$=\".pdf\"]: termina en .pdf */\n  a[href$=\".pdf\"] { color: crimson; font-weight: bold; }\n  input[type=\"email\"] { background: #eff6ff; }\n</style>\n<a href=\"guia.pdf\">Guía PDF</a> <a href=\"inicio.html\">Inicio</a>\n<input type=\"email\" placeholder=\"correo\">", "h": "Destaca los enlaces a PDF y los campos de correo según su atributo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los selectores de atributo se escriben entre ___. (corchetes)", "e": "Olvidar las comillas del valor del atributo."},
  {"m": "Selectores, texto y color", "t": "Pseudoclase hover", "x": "Estado que se activa al pasar el mouse por encima.\n\na:hover se aplica solo mientras el mouse está sobre el enlace. Se usa para cambiar color, fondo o sombra. Combinada con transition (que verás más adelante) da cambios suaves.", "u": "Dar respuesta visual al pasar el cursor.\n\nQuieres que un botón cambie de color mientras el mouse pasa por encima.", "p": ["La pseudoclase hover actúa cuando el mouse está encima.", "Las pseudoclases se escriben con dos puntos.", "El hover es muy usado en botones y enlaces."], "c": "<style>\n  .boton { background: steelblue; color: white; padding: 10px 18px; border: none; }\n  /* :hover solo se aplica mientras el mouse está encima */\n  .boton:hover { background: darkblue; }\n</style>\n<button class=\"boton\">Pasa el mouse</button>", "h": "Oscurece el botón mientras el mouse está encima.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La pseudoclase del mouse encima se escribe :___. (5 letras)", "e": "Usar hover en pantallas táctiles como única señal. Hover es una pseudoclase y lleva un solo signo de dos puntos: a:hover."},
  {"m": "Selectores, texto y color", "t": "Pseudoclase focus", "x": "Estado de un campo o botón seleccionado con teclado o clic.\n\ninput:focus se aplica cuando el campo está activo. Es clave para la accesibilidad: quien navega con teclado necesita ver dónde está. Nunca quites el contorno sin poner una alternativa visible.", "u": "Mostrar dónde está el cursor o el foco.\n\nQuieres que un campo de texto se resalte cuando el usuario lo selecciona.", "p": ["La pseudoclase focus actúa cuando un elemento está seleccionado.", "Es fundamental para quien navega con el teclado.", "No conviene quitar el contorno de foco sin sustituirlo."], "c": "<style>\n  input { padding: 8px; border: 2px solid #cbd5e1; }\n  /* :focus se aplica cuando el campo está activo */\n  input:focus { border-color: dodgerblue; outline: none; box-shadow: 0 0 6px dodgerblue; }\n</style>\n<input placeholder=\"Haz clic aquí o pulsa Tab\">", "h": "Resalta con un borde azul el campo que está activo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La pseudoclase de un campo activo se escribe :___. (5 letras)", "e": "Quitar el contorno de foco sin poner nada en su lugar."},
  {"m": "Selectores, texto y color", "t": "First-child y nth-child", "x": "Pseudoclases que eligen hijos según su posición.\n\n:first-child elige el primer hijo y :last-child el último. :nth-child(2) elige el segundo y :nth-child(even) los pares. Es la forma clásica de hacer tablas con filas alternadas de color.", "u": "Estilar el primero, el último o filas alternas.\n\nQuieres pintar de gris las filas pares de una lista.", "p": ["La pseudoclase first-child elige el primer hijo.", "La expresión nth-child(even) elige los hijos pares.", "Sirve para filas alternadas de tablas y listas."], "c": "<style>\n  /* even: los pares (2.º, 4.º...) */\n  li:nth-child(even) { background: #e2e8f0; }\n  /* el primero en negrita */\n  li:first-child { font-weight: bold; }\n</style>\n<ul><li>Uno</li><li>Dos</li><li>Tres</li><li>Cuatro</li></ul>", "h": "Alterna el fondo de los elementos pares y pone en negrita el primero.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para elegir los hijos pares se usa nth-child(___). (4 letras)", "e": "Contar desde cero en lugar de desde uno."},
  {"m": "Selectores, texto y color", "t": "Before y after", "x": "Pseudoelementos que añaden contenido antes o después.\n\nCon ::before y ::after se inserta contenido generado mediante la propiedad content. Se usan para iconos, comillas o decoraciones. Llevan dos signos de dos puntos, a diferencia de las pseudoclases. El contenido no se puede seleccionar.", "u": "Añadir adornos o iconos sin tocar el HTML.\n\nQuieres añadir una flecha antes de cada enlace sin cambiar el HTML.", "p": ["Los pseudoelementos se escriben con dos signos de dos puntos.", "La propiedad content define el texto que se inserta.", "El contenido generado no forma parte del HTML."], "c": "<style>\n  /* ::before inserta contenido antes del elemento */\n  a::before { content: \"→ \"; color: tomato; }\n  /* ::after lo inserta después */\n  a::after { content: \" ✓\"; }\n</style>\n<a href=\"#\">Seguir leyendo</a>", "h": "Añade una flecha antes y una marca después de un enlace sin tocar el HTML.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que define el texto de ::before es ___. (7 letras)", "e": "Olvidar la propiedad content y no ver nada."},
  {"m": "Selectores, texto y color", "t": "Propiedad color", "x": "Propiedad que cambia el color del texto.\n\ncolor afecta al texto (y al borde si no tiene otro color). Acepta nombres, hexadecimales, rgb y hsl. Se hereda: lo que pongas en el body llega a casi todos los textos. Cuida el contraste con el fondo.", "u": "Dar color a letras y enlaces.\n\nQuieres cambiar el color de las letras de un título.", "p": ["La propiedad color cambia el color del texto.", "El color del texto se hereda de padres a hijos.", "Hay que cuidar el contraste con el fondo."], "c": "<style>\n  /* color: color del TEXTO; se hereda en los hijos */\n  body { color: #1e293b; }\n  h1 { color: tomato; }\n</style>\n<h1>Título rojo</h1>\n<p>Texto con el color del body</p>", "h": "Cambia el color del texto de la página y de un título.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que cambia el color de las letras es ___. (5 letras)", "e": "Usar color de texto muy parecido al fondo."},
  {"m": "Selectores, texto y color", "t": "Background-color", "x": "Propiedad que da color de fondo a un elemento.\n\nbackground-color pinta el fondo del área del elemento (contenido, relleno y borde). Si no se indica, el fondo es transparente. Combínalo con un color de texto que contraste.", "u": "Colorear el fondo de cajas, botones y páginas.\n\nQuieres dar un fondo azul claro a una caja.", "p": ["La propiedad background-color pinta el fondo.", "Por defecto el fondo de los elementos es transparente.", "Hay que elegir un texto que contraste con el fondo."], "c": "<style>\n  .caja {\n    background-color: #dbeafe;   /* fondo azul claro */\n    color: #1e3a8a;              /* texto azul oscuro: buen contraste */\n    padding: 16px;\n  }\n</style>\n<div class=\"caja\">Caja con fondo de color</div>", "h": "Pinta una caja con fondo claro y texto oscuro que contrasta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad del color de fondo es background-___. (5 letras)", "e": "Poner texto claro sobre un fondo claro."},
  {"m": "Selectores, texto y color", "t": "Font-family", "x": "Propiedad que elige el tipo de letra.\n\nSe escribe una lista de fuentes por orden de preferencia terminada en una familia genérica: font-family: Georgia, serif;. Si el navegador no tiene la primera, usa la siguiente. Los nombres con espacios van entre comillas.", "u": "Definir la tipografía del texto.\n\nQuieres cambiar el tipo de letra de un párrafo y dejar una fuente de respaldo.", "p": ["La propiedad font-family elige el tipo de letra.", "Se escribe una lista de fuentes de respaldo.", "Los nombres con espacios van entre comillas."], "c": "<style>\n  /* Si no existe Georgia, usa cualquier fuente serif */\n  h1 { font-family: Georgia, \"Times New Roman\", serif; }\n  p  { font-family: Arial, Helvetica, sans-serif; }\n</style>\n<h1>Título con serifa</h1>\n<p>Párrafo sin serifa</p>", "h": "Elige una fuente con serifa para el título y otra sin serifa para el párrafo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que elige el tipo de letra es font-___. (6 letras)", "e": "Usar una sola fuente sin respaldo."},
  {"m": "Selectores, texto y color", "t": "Font-size", "x": "Propiedad que fija el tamaño de la letra.\n\nfont-size admite px, em, rem y porcentajes. Lo más recomendable es usar rem para respetar el tamaño que cada persona ha configurado en su navegador. Un texto principal por debajo de 16 px (1 rem) cuesta leer.", "u": "Hacer el texto más grande o más pequeño.\n\nQuieres agrandar la letra de un párrafo.", "p": ["La propiedad font-size cambia el tamaño de la letra.", "La unidad rem respeta el tamaño configurado por el usuario.", "El texto principal debería medir al menos 16 px."], "c": "<style>\n  p  { font-size: 1rem; }     /* tamaño normal */\n  h1 { font-size: 2.5rem; }   /* 2,5 veces el normal */\n  small { font-size: 0.8rem; }\n</style>\n<h1>Grande</h1><p>Normal</p><small>Pequeño</small>", "h": "Da tres tamaños distintos de letra con la unidad rem.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que cambia el tamaño de la letra es font-___. (4 letras)", "e": "Usar letras demasiado pequeñas para el texto principal."},
  {"m": "Selectores, texto y color", "t": "Font-weight y font-style", "x": "Propiedades que controlan negrita y cursiva.\n\nfont-weight va de 100 (fino) a 900 (muy grueso); 400 es normal y 700 es negrita (bold). font-style: italic pone cursiva. Ayudan a crear jerarquía visual sin cambiar de fuente.", "u": "Destacar texto con peso o inclinación.\n\nQuieres un texto en cursiva y otro en negrita sin usar etiquetas HTML.", "p": ["font-weight: bold es lo mismo que 700.", "font-style: italic pone el texto en cursiva.", "El valor 400 equivale al peso normal."], "c": "<style>\n  .negrita { font-weight: 700; }\n  .cursiva { font-style: italic; }\n  .fino    { font-weight: 300; }\n</style>\n<p class=\"negrita\">Negrita</p>\n<p class=\"cursiva\">Cursiva</p>\n<p class=\"fino\">Fino</p>", "h": "Aplica negrita, cursiva y peso fino con tres clases.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que pone el texto en negrita se llama font-___. (6 letras)", "e": "Usar font-weight: 1000 y esperar un efecto mayor."},
  {"m": "Selectores, texto y color", "t": "Line-height", "x": "Propiedad que controla la altura entre líneas de texto.\n\nline-height: 1.5 significa 1,5 veces el tamaño de la letra. Un valor entre 1.4 y 1.7 hace que los párrafos respiren. Se recomienda escribirlo sin unidades para que se adapte al tamaño de letra.", "u": "Hacer los párrafos más fáciles de leer.\n\nQuieres que las líneas de un párrafo largo tengan más aire entre sí.", "p": ["La propiedad line-height controla el espacio entre líneas.", "Un valor entre 1.4 y 1.7 mejora la lectura.", "Se recomienda escribir line-height sin unidad."], "c": "<style>\n  .apretado { line-height: 1; }\n  .comodo   { line-height: 1.6; }  /* sin unidad: se adapta al tamaño de letra */\n</style>\n<p class=\"apretado\">Texto con líneas muy pegadas entre sí, difícil de leer cuando hay muchas.</p>\n<p class=\"comodo\">Texto con líneas más separadas, mucho más cómodo de leer.</p>", "h": "Compara un párrafo con líneas pegadas y otro con interlineado cómodo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad del espacio entre líneas es ___-height. (4 letras)", "e": "Dejar el interlineado en 1 en textos largos."},
  {"m": "Selectores, texto y color", "t": "Text-align y text-decoration", "x": "Propiedades que alinean el texto y lo subrayan o tachan.\n\ntext-align acepta left, center, right y justify. text-decoration acepta underline, line-through y none; con none se quita el subrayado de los enlaces. Alinea a la izquierda los textos largos: el texto centrado cuesta más leer.", "u": "Centrar títulos y quitar subrayados de enlaces.\n\nQuieres centrar un título y quitar el subrayado de un enlace.", "p": ["text-align: center centra el texto horizontalmente.", "text-decoration: none quita el subrayado de un enlace.", "Los textos largos se leen mejor alineados a la izquierda."], "c": "<style>\n  h1 { text-align: center; }\n  a  { text-decoration: none; }\n  .tachado { text-decoration: line-through; color: gray; }\n</style>\n<h1>Título centrado</h1>\n<a href=\"#\">Enlace sin subrayado</a>\n<p class=\"tachado\">Precio anterior: 50 €</p>", "h": "Centra un título, quita el subrayado de un enlace y tacha un precio.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para centrar el texto, text-align vale ___. (6 letras)", "e": "Centrar párrafos largos y dificultar su lectura."},
  {"m": "Selectores, texto y color", "t": "Texto: espaciado y mayúsculas", "x": "Propiedades que cambian el espacio entre letras y las mayúsculas.\n\nletter-spacing añade espacio entre letras y word-spacing entre palabras. text-transform cambia a uppercase (mayúsculas), lowercase (minúsculas) o capitalize (primera letra). La transformación no cambia el HTML, solo lo que se ve.", "u": "Dar personalidad a títulos y etiquetas.\n\nQuieres mostrar un título en mayúsculas con letras algo separadas sin reescribirlo.", "p": ["letter-spacing cambia el espacio entre letras.", "text-transform: uppercase muestra el texto en mayúsculas.", "text-transform no modifica el texto original del HTML."], "c": "<style>\n  h2 { text-transform: uppercase; letter-spacing: 3px; }\n  .nombre { text-transform: capitalize; }\n</style>\n<h2>Menú del día</h2>\n<p class=\"nombre\">ana pérez gómez</p>", "h": "Muestra un título en mayúsculas separadas y un nombre con inicial capital.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que cambia a mayúsculas o minúsculas es text-___. (9 letras)", "e": "Escribir el texto en mayúsculas en el HTML en lugar de usar CSS."},
  {"m": "La caja, el espacio y la posición", "t": "Modelo de caja", "x": "Idea de que cada elemento es una caja con capas.\n\nCada elemento es una caja formada, de dentro hacia fuera, por el contenido, el relleno (padding), el borde (border) y el margen (margin). Para calcular el tamaño real de un elemento hay que sumar todas las capas.", "u": "Entender cuánto espacio ocupa cada elemento.\n\nQuieres entender por qué una caja de 200 px de ancho ocupa más espacio en pantalla.", "p": ["Una caja se compone de contenido, relleno, borde y margen.", "El padding está dentro del borde y el margin fuera.", "El tamaño total de una caja suma todas sus capas."], "c": "<style>\n  .caja {\n    width: 200px;           /* contenido */\n    padding: 20px;          /* relleno */\n    border: 5px solid navy; /* borde */\n    margin: 30px;           /* margen */\n    background: #dbeafe;\n  }\n</style>\n<div class=\"caja\">Caja con todas sus capas</div>", "h": "Muestra una caja con contenido, relleno, borde y margen.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: De dentro hacia fuera: contenido, relleno, borde y ___. (6 letras)", "e": "Olvidar sumar padding y borde al tamaño de la caja."},
  {"m": "La caja, el espacio y la posición", "t": "Margin", "x": "Espacio exterior que separa un elemento de los demás.\n\nmargin: 20px da 20 px por los cuatro lados. Con dos valores (10px 20px) el primero es vertical y el segundo horizontal; con cuatro van en el sentido de las agujas del reloj: arriba, derecha, abajo, izquierda. Los márgenes verticales vecinos pueden fusionarse.", "u": "Dejar aire entre elementos.\n\nQuieres separar una caja de las que tiene a su alrededor.", "p": ["El margin es el espacio exterior de un elemento.", "Con cuatro valores el orden es arriba, derecha, abajo, izquierda.", "Los márgenes verticales de vecinos pueden fusionarse."], "c": "<style>\n  .a, .b { background: lightblue; }\n  /* margin: arriba derecha abajo izquierda */\n  .a { margin: 10px 40px 20px 40px; }\n  .b { margin: 0 0 0 80px; }\n</style>\n<div class=\"a\">Caja A</div>\n<div class=\"b\">Caja B</div>", "h": "Coloca dos cajas con márgenes distintos en sus cuatro lados.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Con cuatro valores el orden del margin es arriba, derecha, abajo y ___. (9 letras)", "e": "Confundir el orden de los cuatro valores."},
  {"m": "La caja, el espacio y la posición", "t": "Padding", "x": "Espacio interior entre el contenido y el borde.\n\npadding funciona como margin pero hacia dentro. El fondo del elemento sí cubre el padding. Un botón sin padding se ve apretado, y por eso casi todos los botones lo llevan.", "u": "Dar aire dentro de una caja.\n\nQuieres separar el texto de un botón de sus bordes.", "p": ["El padding es el espacio interior de un elemento.", "El color de fondo cubre el área del padding.", "Los botones suelen necesitar padding para verse cómodos."], "c": "<style>\n  .boton { background: seagreen; color: white; border: none; }\n  .sin { padding: 0; }\n  .con { padding: 12px 28px; }   /* vertical horizontal */\n</style>\n<button class=\"boton sin\">Sin padding</button>\n<button class=\"boton con\">Con padding</button>", "h": "Compara un botón sin relleno con otro cómodo y espacioso.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El espacio entre el contenido y el borde es el ___. (7 letras)", "e": "Usar margin cuando se quería espacio interior."},
  {"m": "La caja, el espacio y la posición", "t": "Border", "x": "Línea que rodea al elemento.\n\nSe escribe con tres valores: grosor, estilo y color. Ejemplo: border: 2px solid red;. Los estilos más usados son solid, dashed y dotted. También se puede poner solo un lado con border-bottom.", "u": "Enmarcar cajas, tarjetas y campos.\n\nQuieres dibujar una línea discontinua alrededor de una caja.", "p": ["La propiedad border lleva grosor, estilo y color.", "Los estilos más usados son solid, dashed y dotted.", "Se puede aplicar un borde a un solo lado."], "c": "<style>\n  .a { border: 3px solid crimson; padding: 8px; }\n  .b { border: 3px dashed teal; padding: 8px; }\n  /* solo el borde inferior */\n  .c { border-bottom: 4px dotted orange; padding: 8px; }\n</style>\n<p class=\"a\">Continuo</p><p class=\"b\">Discontinuo</p><p class=\"c\">Solo abajo</p>", "h": "Muestra bordes continuo, discontinuo y solo inferior.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En border: 2px solid red, «solid» es el ___ del borde. (5 letras)", "e": "Olvidar el estilo y no ver el borde. Falta el estilo del borde (solid, dashed...): sin él no se dibuja."},
  {"m": "La caja, el espacio y la posición", "t": "Border-radius", "x": "Propiedad que redondea las esquinas.\n\nborder-radius: 12px redondea las cuatro esquinas. Con 50% en una caja cuadrada se obtiene un círculo. Se pueden dar valores distintos a cada esquina.", "u": "Suavizar tarjetas y botones o hacer círculos.\n\nQuieres convertir una caja cuadrada en un círculo.", "p": ["border-radius redondea las esquinas de un elemento.", "Con 50% una caja cuadrada se vuelve un círculo.", "Cada esquina puede tener un radio distinto."], "c": "<style>\n  .tarjeta { border-radius: 16px; background: #fde68a; padding: 16px; width: 160px; }\n  /* 50% en un cuadrado = círculo */\n  .circulo { width: 100px; height: 100px; background: tomato; border-radius: 50%; }\n</style>\n<div class=\"tarjeta\">Esquinas suaves</div>\n<div class=\"circulo\"></div>", "h": "Redondea una tarjeta y convierte un cuadrado en círculo.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para un círculo, border-radius vale ___%. (un número)", "e": "Aplicar 50% a un rectángulo y obtener una elipse sin querer."},
  {"m": "La caja, el espacio y la posición", "t": "Width y height", "x": "Propiedades que fijan el ancho y el alto de un elemento.\n\nwidth y height fijan el tamaño del contenido. Si no pones height, la altura se adapta al contenido, lo cual es casi siempre lo mejor. min-width, max-width, min-height y max-height ponen límites.", "u": "Controlar el tamaño de cajas e imágenes.\n\nQuieres que una caja mida exactamente 300 píxeles de ancho.", "p": ["Width fija el ancho y height fija el alto.", "Sin height, la altura se adapta al contenido.", "Las propiedades max-width y min-width ponen límites."], "c": "<style>\n  .caja { width: 300px; background: #bbf7d0; padding: 10px; }\n  /* la altura se adapta al contenido salvo que la fijes */\n  .alta { height: 120px; background: #fecaca; }\n</style>\n<div class=\"caja\">Ancho fijo, alto automático</div>\n<div class=\"caja alta\">Con altura fija</div>", "h": "Muestra una caja de ancho fijo y otra con altura fija.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que fija el ancho es ___. (5 letras)", "e": "Fijar la altura y que el texto se desborde."},
  {"m": "La caja, el espacio y la posición", "t": "Box-sizing", "x": "Propiedad que decide cómo se calcula el tamaño de la caja.\n\nCon content-box (valor por defecto), width solo cuenta el contenido y se suma el padding y el borde. Con box-sizing: border-box, width incluye todo y la caja mide justo lo que escribiste. Casi todos los proyectos lo aplican a todos los elementos.", "u": "Evitar que padding y borde agranden la caja.\n\nQuieres que una caja de 200 px mida 200 px aunque tenga padding y borde.", "p": ["Con border-box, el width incluye padding y borde.", "El valor por defecto es content-box.", "Muchos proyectos aplican border-box a todos los elementos."], "c": "<style>\n  .normal { width: 200px; padding: 20px; border: 5px solid black; background: #fef08a; }\n  .borde  { width: 200px; padding: 20px; border: 5px solid black; background: #bae6fd;\n            box-sizing: border-box; }\n</style>\n<div class=\"normal\">content-box: mide 250 px</div>\n<div class=\"borde\">border-box: mide 200 px</div>", "h": "Compara una caja que crece con el padding y otra que mantiene su ancho.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor que incluye padding y borde en el width es ___-box. (6 letras)", "e": "Olvidar border-box y ver cajas que se salen del contenedor."},
  {"m": "La caja, el espacio y la posición", "t": "Display", "x": "Propiedad que decide cómo se comporta un elemento en el flujo.\n\nLos elementos block (div, p, h1) ocupan todo el ancho y empiezan en una línea nueva. Los inline (span, a) solo ocupan su contenido y no aceptan width ni height. inline-block mezcla ambos: va en línea pero acepta tamaño.", "u": "Cambiar un elemento de bloque a línea o viceversa.\n\nQuieres que varios divs se coloquen uno al lado del otro con tamaño propio.", "p": ["Los elementos block ocupan todo el ancho disponible.", "Los elementos inline no aceptan width ni height.", "inline-block va en línea pero admite tamaño."], "c": "<style>\n  .item { display: inline-block; width: 90px; height: 60px; background: coral; margin: 4px; }\n  .bloque { display: block; background: lightgreen; }\n</style>\n<div class=\"item\">1</div><div class=\"item\">2</div><div class=\"item\">3</div>\n<span class=\"bloque\">Un span convertido en bloque</span>", "h": "Coloca tres cajas con tamaño una junto a otra y convierte un span en bloque.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor de display que mezcla línea y tamaño es inline-___. (5 letras)", "e": "Dar width a un elemento inline y no ver el cambio."},
  {"m": "La caja, el espacio y la posición", "t": "Display none", "x": "Valor que oculta un elemento y libera su espacio.\n\ndisplay: none hace que el elemento desaparezca y no ocupe espacio. Es distinto de visibility: hidden, que lo oculta pero conserva su hueco. Los lectores de pantalla tampoco leen lo que tiene display: none.", "u": "Esconder contenido sin borrarlo del HTML.\n\nQuieres ocultar un aviso por completo para que ni siquiera ocupe espacio.", "p": ["display: none oculta el elemento y su espacio.", "visibility: hidden oculta pero mantiene el hueco.", "Un elemento con display: none no se lee en lectores de pantalla."], "c": "<style>\n  .oculto  { display: none; }            /* desaparece y no ocupa espacio */\n  .invisible { visibility: hidden; }     /* desaparece pero deja el hueco */\n</style>\n<p>Uno</p>\n<p class=\"oculto\">Dos (no ocupa espacio)</p>\n<p class=\"invisible\">Tres (deja su hueco)</p>\n<p>Cuatro</p>", "h": "Oculta un párrafo sin hueco y otro dejando su hueco.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor de display que oculta un elemento es ___. (4 letras)", "e": "Confundir display none con visibility hidden."},
  {"m": "La caja, el espacio y la posición", "t": "Overflow", "x": "Propiedad que decide qué pasa con el contenido que no cabe.\n\nSi el contenido es más grande que la caja, overflow decide: visible (se sale), hidden (se corta), scroll (muestra barras) o auto (barras solo si hace falta). Ocultar sin avisar puede esconder información importante.", "u": "Controlar los desbordes de texto o imágenes.\n\nQuieres que una caja pequeña muestre barras de desplazamiento si su texto no cabe.", "p": ["overflow decide qué pasa si el contenido no cabe.", "overflow: auto añade barras solo cuando hacen falta.", "overflow: hidden corta lo que sobra."], "c": "<style>\n  .caja { width: 180px; height: 70px; border: 2px solid gray; }\n  .a { overflow: hidden; }   /* corta lo que sobra */\n  .b { overflow: auto; }     /* barra si hace falta */\n</style>\n<div class=\"caja a\">Mucho texto, mucho texto, mucho texto, mucho texto, mucho texto.</div>\n<div class=\"caja b\">Mucho texto, mucho texto, mucho texto, mucho texto, mucho texto.</div>", "h": "Corta el texto sobrante en una caja y añade barra en otra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor de overflow que añade barra solo si hace falta es ___. (4 letras)", "e": "Ocultar con hidden información que el usuario necesita."},
  {"m": "La caja, el espacio y la posición", "t": "Centrar con margin auto", "x": "Técnica de centrar una caja horizontalmente.\n\nPara centrar un bloque horizontalmente, dale un ancho y pon margin: 0 auto;. Los márgenes automáticos izquierdo y derecho se reparten el espacio sobrante. Funciona en elementos de bloque con width definido.", "u": "Colocar una caja en el centro de su contenedor.\n\nQuieres centrar un bloque de 400 px de ancho en medio de la página.", "p": ["margin: 0 auto centra una caja de bloque horizontalmente.", "La caja necesita un ancho definido para poder centrarse.", "Los márgenes automáticos se reparten el espacio sobrante."], "c": "<style>\n  .centrada {\n    width: 300px;\n    margin: 0 auto;     /* arriba/abajo 0; izquierda/derecha automáticos */\n    background: #c7d2fe;\n    padding: 12px;\n    text-align: center;\n  }\n</style>\n<div class=\"centrada\">Estoy centrada</div>", "h": "Centra horizontalmente una caja de 300 píxeles.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para centrar una caja se usa margin: 0 ___. (4 letras)", "e": "Olvidar el ancho y no ver centrada la caja."},
  {"m": "La caja, el espacio y la posición", "t": "Max-width", "x": "Propiedad que limita el ancho máximo.\n\nmax-width: 700px deja que la caja se encoja en pantallas pequeñas pero nunca supere 700 px. Para textos largos se recomienda un ancho de unos 60 a 75 caracteres por línea. Con imágenes, max-width: 100% evita que se salgan.", "u": "Evitar que el contenido se estire demasiado en pantallas grandes.\n\nQuieres que tu texto no se estire por toda la pantalla en un monitor grande.", "p": ["max-width limita el ancho máximo de un elemento.", "Un texto largo se lee mejor con líneas de ancho limitado.", "Una imagen con max-width: 100% no se sale de su contenedor."], "c": "<style>\n  .texto {\n    max-width: 500px;      /* nunca más ancho que esto */\n    margin: 0 auto;\n    background: #f1f5f9;\n    padding: 12px;\n  }\n  img { max-width: 100%; }  /* las imágenes nunca se salen */\n</style>\n<div class=\"texto\">Este texto se estira hasta 500 px y no más, aunque la pantalla sea enorme.</div>", "h": "Limita a 500 píxeles el ancho de un texto y evita que las imágenes se salgan.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que limita el ancho máximo es ___-width. (3 letras)", "e": "Usar width fijo y provocar desplazamiento horizontal en móviles."},
  {"m": "La caja, el espacio y la posición", "t": "Position relative", "x": "Posición que desplaza un elemento respecto a su sitio original.\n\nCon position: relative el elemento sigue ocupando su sitio, pero puedes moverlo con top, left, right y bottom. También es la forma de crear un punto de referencia para los hijos con position absolute.", "u": "Mover un elemento un poco y servir de referencia a otros.\n\nQuieres mover un elemento unos píxeles sin sacarlo del flujo de la página.", "p": ["position: relative mueve el elemento respecto a su lugar original.", "El hueco original del elemento se conserva.", "Se usa como referencia para hijos con position absolute."], "c": "<style>\n  .normal  { background: #fecaca; padding: 10px; }\n  .movida  { position: relative; top: 15px; left: 40px; background: #bbf7d0; padding: 10px; }\n</style>\n<div class=\"normal\">Normal</div>\n<div class=\"movida\">Relative: movida 15px abajo y 40px a la derecha</div>\n<div class=\"normal\">Otra normal (el hueco se conserva)</div>", "h": "Desplaza una caja respecto a su posición original manteniendo su hueco.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La posición que desplaza respecto al lugar original es ___. (8 letras)", "e": "Creer que relative saca al elemento del flujo."},
  {"m": "La caja, el espacio y la posición", "t": "Position absolute", "x": "Posición que saca al elemento del flujo y lo coloca con coordenadas.\n\nUn elemento con position: absolute se posiciona con top, left, right y bottom respecto al antecesor más cercano que tenga position distinta de static. Si no hay ninguno, usa la página. Ya no ocupa espacio en el flujo.", "u": "Colocar un elemento en una esquina de su contenedor.\n\nQuieres pegar una etiqueta «Nuevo» en la esquina superior derecha de una tarjeta.", "p": ["position: absolute saca al elemento del flujo normal.", "Se coloca respecto al antecesor posicionado más cercano.", "Se usa con top, right, bottom y left."], "c": "<style>\n  .tarjeta { position: relative; width: 200px; height: 100px; background: #e0e7ff; }\n  /* absolute se coloca respecto a .tarjeta (que es relative) */\n  .etiqueta { position: absolute; top: 8px; right: 8px; background: crimson; color: white; padding: 2px 8px; }\n</style>\n<div class=\"tarjeta\"><span class=\"etiqueta\">Nuevo</span>Producto</div>", "h": "Pega una etiqueta en la esquina superior derecha de una tarjeta.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La posición que usa coordenadas respecto a su antecesor es ___. (8 letras)", "e": "Olvidar position relative en el contenedor. Falta cerrar la llave de la regla .padre antes de </style>."},
  {"m": "La caja, el espacio y la posición", "t": "Position fixed y sticky", "x": "Posiciones que fijan elementos en la ventana al desplazarse.\n\nCon fixed el elemento queda clavado a la ventana y no se mueve al hacer scroll (por ejemplo un botón de chat). Con sticky se comporta como relativo hasta llegar a cierto punto y entonces se pega. Es ideal para cabeceras de tablas y menús.", "u": "Mantener visibles menús y botones mientras se hace scroll.\n\nQuieres que un menú se quede pegado arriba mientras el usuario baja por la página.", "p": ["position: fixed se mantiene fijo en la ventana.", "position: sticky se pega al llegar a un punto del scroll.", "Los menús que acompañan al desplazarse usan sticky o fixed."], "c": "<style>\n  .menu { position: sticky; top: 0; background: navy; color: white; padding: 10px; }\n  .chat { position: fixed; bottom: 16px; right: 16px; background: seagreen; color: white; padding: 10px; }\n  .relleno { height: 600px; background: #f1f5f9; }\n</style>\n<div class=\"menu\">Menú pegajoso</div>\n<div class=\"relleno\">Haz scroll</div>\n<div class=\"chat\">Chat fijo</div>", "h": "Deja un menú pegado arriba y un botón fijo en la esquina al hacer scroll.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La posición que se pega al llegar a cierto punto es ___. (6 letras)", "e": "Cubrir contenido importante con un elemento fixed."},
  {"m": "La caja, el espacio y la posición", "t": "Z-index", "x": "Propiedad que decide qué elemento queda delante.\n\nCuando dos elementos se solapan, z-index: un número mayor queda por encima. Solo funciona en elementos con position distinta de static. Evita números gigantes: usa una escala sencilla como 10, 20 y 30.", "u": "Ordenar elementos que se superponen.\n\nDos cajas se solapan y quieres que una quede delante de la otra.", "p": ["Un z-index mayor queda por encima de uno menor.", "El z-index funciona en elementos posicionados.", "Conviene usar una escala sencilla de valores."], "c": "<style>\n  .caja { position: absolute; width: 100px; height: 80px; }\n  .roja { background: tomato; top: 20px; left: 20px; z-index: 1; }\n  .azul { background: dodgerblue; top: 50px; left: 60px; z-index: 2; }  /* queda encima */\n</style>\n<div style=\"position:relative;height:150px\">\n  <div class=\"caja roja\">1</div><div class=\"caja azul\">2</div>\n</div>", "h": "Superpone dos cajas y deja la azul por delante con un z-index mayor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que ordena elementos superpuestos es ___-index. (1 letra)", "e": "Usar z-index en un elemento sin position."},
  {"m": "La caja, el espacio y la posición", "t": "Box-shadow", "x": "Propiedad que dibuja una sombra alrededor de la caja.\n\nSe escribe con desplazamiento horizontal, vertical, desenfoque y color: box-shadow: 0 4px 10px rgba(0,0,0,0.2);. Una sombra suave da sensación de elevación. Con inset la sombra se dibuja por dentro.", "u": "Dar profundidad a tarjetas y botones.\n\nQuieres que una tarjeta parezca levantada sobre la página con una sombra.", "p": ["box-shadow dibuja una sombra alrededor de la caja.", "Sus valores son desplazamiento, desenfoque y color.", "Una sombra suave da sensación de elevación."], "c": "<style>\n  .tarjeta {\n    background: white; padding: 20px; width: 200px; border-radius: 12px;\n    /* x  y  desenfoque  color */\n    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.2);\n  }\n  body { background: #e2e8f0; }\n</style>\n<div class=\"tarjeta\">Tarjeta elevada</div>", "h": "Da una sombra suave a una tarjeta blanca sobre un fondo gris.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad de la sombra de una caja es box-___. (6 letras)", "e": "Usar sombras muy oscuras y duras."},
  {"m": "La caja, el espacio y la posición", "t": "Rem y em", "x": "Unidades relativas al tamaño de la letra.\n\n1 em equivale al tamaño de letra del propio elemento (o de su padre) y 1 rem al tamaño de letra de la raíz (html), normalmente 16 px. Los rem son más predecibles porque no se acumulan al anidar. Con rem, el diseño respeta si la persona agranda el texto del navegador.", "u": "Crear tamaños que se adaptan al texto del usuario.\n\nQuieres un tamaño que crezca si el usuario aumenta el texto del navegador.", "p": ["1 rem es el tamaño de letra del elemento raíz.", "Los em dependen del tamaño de letra del elemento o de su padre.", "Los rem no se acumulan al anidar elementos."], "c": "<style>\n  html { font-size: 16px; }          /* 1rem = 16px */\n  h1 { font-size: 2rem; }            /* 32px */\n  p  { font-size: 1rem; margin-bottom: 1.5rem; }\n  .caja { padding: 1rem; background: #fef3c7; }\n</style>\n<h1>Rem en acción</h1>\n<p>Texto de tamaño base.</p>\n<div class=\"caja\">Relleno de 1rem</div>", "h": "Define tamaños, márgenes y rellenos con la unidad rem.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: 1rem equivale por defecto a ___ píxeles. (un número)", "e": "Usar em anidados y ver tamaños que se multiplican."},
  {"m": "La caja, el espacio y la posición", "t": "Porcentajes y vw vh", "x": "Unidades que dependen del contenedor o de la ventana.\n\nEl % se calcula respecto al elemento padre. vw es el 1 % del ancho de la ventana y vh el 1 % de su alto. Así, height: 100vh ocupa toda la altura visible, algo muy útil en pantallas de bienvenida.", "u": "Adaptar tamaños al espacio disponible.\n\nQuieres que una sección ocupe toda la altura de la ventana del navegador.", "p": ["El % toma como referencia al elemento padre.", "1vw es el 1 % del ancho de la ventana.", "100vh ocupa toda la altura visible de la ventana."], "c": "<style>\n  .mitad { width: 50%; background: lightblue; }\n  .portada { height: 60vh; background: #fde68a; display: grid; place-items: center; }\n</style>\n<div class=\"mitad\">50% del padre</div>\n<div class=\"portada\">Ocupo el 60% de la altura de la ventana</div>", "h": "Ocupa la mitad del ancho del padre y el 60 % de la altura de la ventana.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La unidad del 1 % del alto de la ventana es ___. (2 letras)", "e": "Usar 100vw y provocar una barra de desplazamiento horizontal."},
  {"m": "La caja, el espacio y la posición", "t": "Imagen de fondo", "x": "Propiedades para poner una imagen detrás del contenido.\n\nbackground-image: url(...) coloca la imagen. background-size: cover la escala para cubrir todo el espacio y background-position la centra. background-repeat: no-repeat evita que se repita en mosaico. El contenido importante no debería depender solo de la imagen.", "u": "Crear portadas y fondos decorativos.\n\nQuieres que una foto cubra todo el fondo de una cabecera.", "p": ["background-image coloca una imagen de fondo.", "background-size: cover cubre todo el espacio.", "background-repeat: no-repeat evita el mosaico."], "c": "<style>\n  .portada {\n    height: 160px;\n    background-image: linear-gradient(135deg, #38bdf8, #6366f1); /* o url(\"foto.jpg\") */\n    background-size: cover;\n    background-position: center;\n    background-repeat: no-repeat;\n    color: white; display: grid; place-items: center; font-size: 1.5rem;\n  }\n</style>\n<div class=\"portada\">Texto sobre la imagen de fondo</div>", "h": "Cubre una cabecera con una imagen de fondo bien ajustada y centrada.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor de background-size que cubre todo el espacio es ___. (5 letras)", "e": "Poner texto claro sobre una imagen clara."},
  {"m": "Flexbox y Grid", "t": "Flexbox", "x": "Sistema de CSS para alinear elementos en una fila o columna.\n\nPones display: flex en el contenedor y sus hijos directos pasan a ser elementos flexibles. Se colocan en fila, se reparten el espacio y se alinean con pocas propiedades. Es la herramienta ideal para menús, barras y tarjetas en línea.", "u": "Ordenar elementos en una dimensión con facilidad.\n\nQuieres colocar tres cajas en fila de forma sencilla.", "p": ["Flexbox se activa con display: flex en el contenedor.", "Los hijos directos del contenedor se vuelven elementos flexibles.", "Flexbox organiza los elementos en una sola dimensión."], "c": "<style>\n  .fila { display: flex; gap: 10px; }      /* contenedor flex */\n  .fila div { background: #a5b4fc; padding: 20px; }\n</style>\n<div class=\"fila\"><div>1</div><div>2</div><div>3</div></div>", "h": "Coloca tres cajas en una fila usando un contenedor flexible.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Flexbox se activa con display: ___. (4 letras)", "e": "Aplicar display flex a los hijos en vez de al contenedor. display: flex debe ir en el contenedor (.caja), no en sus hijos."},
  {"m": "Flexbox y Grid", "t": "Flex-direction", "x": "Propiedad que define si los elementos van en fila o en columna.\n\nrow (por defecto) coloca en fila de izquierda a derecha, column los apila de arriba a abajo, y row-reverse y column-reverse invierten el orden. Al cambiarla, el eje principal y el secundario se intercambian.", "u": "Cambiar la dirección principal del contenedor flex.\n\nQuieres que los elementos de un contenedor flex se apilen uno debajo de otro.", "p": ["flex-direction: column apila los elementos de arriba a abajo.", "El valor por defecto es row.", "Cambiar la dirección intercambia los ejes principal y secundario."], "c": "<style>\n  .columna { display: flex; flex-direction: column; gap: 8px; width: 160px; }\n  .columna div { background: #fda4af; padding: 12px; }\n</style>\n<div class=\"columna\"><div>Arriba</div><div>Medio</div><div>Abajo</div></div>", "h": "Apila tres cajas verticalmente cambiando la dirección del contenedor.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor de flex-direction que apila elementos es ___. (6 letras)", "e": "Olvidar que al cambiar la dirección cambian los ejes."},
  {"m": "Flexbox y Grid", "t": "Justify-content", "x": "Propiedad que reparte los elementos en el eje principal.\n\nValores habituales: flex-start (al inicio), center (al centro), flex-end (al final), space-between (espacio entre ellos) y space-around o space-evenly. Con filas, actúa en horizontal; con columnas, en vertical.", "u": "Alinear o distribuir elementos a lo largo de la fila.\n\nQuieres separar al máximo tres botones dentro de una barra, con el primero a la izquierda y el último a la derecha.", "p": ["justify-content actúa sobre el eje principal.", "space-between reparte el espacio sobrante entre los elementos.", "center agrupa los elementos en el centro del eje."], "c": "<style>\n  .barra { display: flex; justify-content: space-between; background: #e2e8f0; padding: 8px; }\n  .barra span { background: #6366f1; color: white; padding: 6px 12px; }\n</style>\n<div class=\"barra\"><span>Izq</span><span>Centro</span><span>Der</span></div>", "h": "Reparte tres elementos de lado a lado con espacio entre ellos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor que reparte espacio entre los elementos es space-___. (7 letras)", "e": "Usar justify-content esperando que alinee en vertical con filas."},
  {"m": "Flexbox y Grid", "t": "Align-items", "x": "Propiedad que alinea los elementos en el eje secundario.\n\nEn una fila, align-items controla la alineación vertical: flex-start, center, flex-end, stretch (por defecto, estira) o baseline. Si el contenedor tiene altura, align-items: center centra los hijos verticalmente.", "u": "Centrar o estirar elementos en vertical dentro de una fila.\n\nQuieres centrar verticalmente los elementos de una fila con altura fija.", "p": ["align-items actúa sobre el eje secundario.", "El valor por defecto es stretch.", "align-items: center centra los elementos en el eje secundario."], "c": "<style>\n  .fila { display: flex; align-items: center; height: 120px; background: #fef9c3; gap: 8px; }\n  .fila div { background: #f59e0b; padding: 10px; }\n  .alto { height: 70px; }\n</style>\n<div class=\"fila\"><div>Bajo</div><div class=\"alto\">Alto</div><div>Bajo</div></div>", "h": "Centra verticalmente cajas de distinta altura dentro de una fila.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que alinea en el eje secundario es align-___. (5 letras)", "e": "Confundir justify-content con align-items."},
  {"m": "Flexbox y Grid", "t": "Flex-wrap", "x": "Propiedad que permite pasar a otra línea cuando no caben.\n\nPor defecto, flex-wrap vale nowrap y todos los elementos intentan caber en una línea, encogiéndose. Con flex-wrap: wrap, los que no caben saltan a la línea siguiente. Es clave para tarjetas que se adaptan al ancho.", "u": "Evitar que los elementos se aprieten o se salgan.\n\nQuieres que las tarjetas que no caben en una fila pasen a la siguiente línea.", "p": ["flex-wrap: wrap permite que los elementos pasen a otra línea.", "El valor por defecto es nowrap.", "Con wrap, los elementos no se encogen hasta el límite."], "c": "<style>\n  .lista { display: flex; flex-wrap: wrap; gap: 10px; width: 330px; }\n  .lista div { width: 100px; padding: 16px; background: #86efac; }\n</style>\n<div class=\"lista\"><div>1</div><div>2</div><div>3</div><div>4</div><div>5</div></div>", "h": "Deja que cinco tarjetas pasen a una segunda línea cuando no caben.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor de flex-wrap que permite varias líneas es ___. (4 letras)", "e": "Olvidar wrap y ver elementos aplastados."},
  {"m": "Flexbox y Grid", "t": "Gap", "x": "Propiedad que añade espacio entre elementos flex o grid.\n\ngap: 16px separa todos los hijos entre sí, sin añadir espacio en los bordes del contenedor. Existe row-gap y column-gap para controlar cada dirección. Es más limpio que poner margin a cada elemento.", "u": "Separar elementos sin usar márgenes.\n\nQuieres separar los elementos de un contenedor sin añadir márgenes a cada uno.", "p": ["gap añade espacio entre los elementos hijos.", "gap no añade espacio en los bordes del contenedor.", "Existen row-gap y column-gap para cada dirección."], "c": "<style>\n  .fila { display: flex; gap: 24px; }           /* espacio entre elementos */\n  .fila div { background: #7dd3fc; padding: 14px; }\n</style>\n<div class=\"fila\"><div>A</div><div>B</div><div>C</div></div>", "h": "Separa tres cajas con 24 píxeles de espacio entre ellas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que añade espacio entre hijos de flex o grid es ___. (3 letras)", "e": "Usar margin en cada hijo cuando bastaba con gap."},
  {"m": "Flexbox y Grid", "t": "Flex-grow", "x": "Propiedad que permite a un elemento ocupar el espacio libre.\n\nflex-grow: 1 reparte el espacio sobrante entre los elementos que lo tengan. Si uno tiene 2 y otro 1, el primero recibe el doble. Un campo de búsqueda con flex-grow: 1 ocupa todo lo que deja libre el botón.", "u": "Hacer que un elemento se estire y llene lo que sobra.\n\nQuieres que un campo de búsqueda ocupe todo el espacio que sobra junto a un botón.", "p": ["flex-grow reparte el espacio libre entre los elementos.", "Un elemento con valor 2 recibe el doble que otro con valor 1.", "Por defecto flex-grow vale 0."], "c": "<style>\n  .buscador { display: flex; gap: 8px; }\n  .buscador input { flex-grow: 1; padding: 8px; }   /* ocupa el espacio libre */\n</style>\n<div class=\"buscador\"><input placeholder=\"Buscar...\"><button>Ir</button></div>", "h": "Estira el campo de búsqueda para llenar el espacio junto al botón.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que ocupa el espacio libre es flex-___. (4 letras)", "e": "Dar flex-grow a todos los elementos y no ver diferencias."},
  {"m": "Flexbox y Grid", "t": "Flex abreviado", "x": "Propiedad que combina crecer, encoger y base en una línea.\n\nflex: 1 equivale a crecer 1, encoger 1 y base 0: reparte el espacio por igual. flex: 0 0 200px fija un tamaño de 200 px sin crecer ni encoger. flex-shrink controla cuánto se encoge y flex-basis el tamaño de partida.", "u": "Controlar el tamaño de un elemento flex de forma compacta.\n\nQuieres tres columnas del mismo ancho que se repartan todo el espacio.", "p": ["flex: 1 reparte el espacio de forma equitativa.", "flex-basis define el tamaño inicial del elemento.", "flex-shrink controla cuánto se encoge un elemento."], "c": "<style>\n  .fila { display: flex; gap: 8px; }\n  .fila div { flex: 1; background: #fbcfe8; padding: 14px; text-align: center; }\n  .fila .fija { flex: 0 0 120px; background: #f9a8d4; }\n</style>\n<div class=\"fila\"><div>1</div><div>2</div><div class=\"fija\">Fija 120px</div></div>", "h": "Reparte el espacio por igual y fija una columna a 120 píxeles.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para repartir el espacio por igual entre hijos se usa flex: ___. (un número)", "e": "Olvidar que flex: 1 deja la base en cero."},
  {"m": "Flexbox y Grid", "t": "Align-self", "x": "Propiedad que alinea un solo elemento en el eje secundario.\n\nMientras align-items actúa sobre todos los hijos desde el contenedor, align-self se pone en un hijo y cambia solo su alineación. Acepta los mismos valores: flex-start, center, flex-end o stretch.", "u": "Romper la alineación del grupo en un único hijo.\n\nQuieres que solo uno de los elementos de una fila se alinee abajo.", "p": ["align-self alinea a un solo elemento.", "align-self sustituye a align-items para ese hijo.", "Se escribe en el hijo, no en el contenedor."], "c": "<style>\n  .fila { display: flex; align-items: flex-start; height: 110px; background: #ddd6fe; gap: 8px; }\n  .fila div { background: #7c3aed; color: white; padding: 10px; }\n  .abajo { align-self: flex-end; }    /* solo este baja */\n</style>\n<div class=\"fila\"><div>Arriba</div><div class=\"abajo\">Abajo</div><div>Arriba</div></div>", "h": "Baja un único elemento al fondo de la fila mientras los demás quedan arriba.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que alinea a un solo hijo es align-___. (4 letras)", "e": "Escribir align-self en el contenedor."},
  {"m": "Flexbox y Grid", "t": "Order", "x": "Propiedad que cambia el orden visual de los elementos flex.\n\nPor defecto todos los elementos tienen order: 0 y siguen el orden del HTML. Con order: -1 un elemento pasa al principio y con order: 1 al final. Úsalo con cuidado: el orden de lectura con teclado sigue el del HTML.", "u": "Reordenar elementos sin tocar el HTML.\n\nQuieres que el último elemento se muestre primero sin reescribir el HTML.", "p": ["order cambia el orden visual de los elementos.", "Todos los elementos parten con order: 0.", "El orden de tabulación sigue siendo el del HTML."], "c": "<style>\n  .fila { display: flex; gap: 8px; }\n  .fila div { background: #fde68a; padding: 12px; }\n  .fila .ultimo { order: -1; background: #fb923c; }   /* pasa al principio */\n</style>\n<div class=\"fila\"><div>A</div><div>B</div><div class=\"ultimo\">C (primero)</div></div>", "h": "Muestra el tercer elemento al principio sin cambiar el HTML.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que cambia el orden visual es ___. (5 letras)", "e": "Reordenar con order y olvidar el orden del teclado."},
  {"m": "Flexbox y Grid", "t": "Centrar con flexbox", "x": "Técnica que centra un elemento en horizontal y vertical.\n\nCon display: flex, justify-content: center y align-items: center el contenido queda exactamente en el centro. El contenedor necesita altura para que se note el centrado vertical. Es la solución clásica a «¿cómo centro un div?».", "u": "Centrar cualquier cosa dentro de su contenedor.\n\nQuieres centrar un mensaje justo en el medio de una caja, en horizontal y vertical.", "p": ["Para centrar con flex se usan justify-content y align-items en center.", "El contenedor necesita altura para centrar en vertical.", "Es la forma moderna de centrar un elemento."], "c": "<style>\n  .caja {\n    display: flex; justify-content: center; align-items: center;\n    height: 140px; background: #bfdbfe;\n  }\n</style>\n<div class=\"caja\"><p>Centrado total</p></div>", "h": "Centra un texto en el medio exacto de una caja.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para centrar en el eje principal se usa justify-content: ___. (6 letras)", "e": "Olvidar dar altura al contenedor."},
  {"m": "Flexbox y Grid", "t": "Barra de navegación", "x": "Menú horizontal construido con flexbox.\n\nUna barra clásica es un nav con una lista ul en display: flex. Se quitan las viñetas con list-style: none, se separan con gap y se alinean con justify-content. Se puede añadir el logo a la izquierda y los enlaces a la derecha.", "u": "Crear el menú principal de una página.\n\nQuieres construir un menú horizontal con el logo a la izquierda y los enlaces a la derecha.", "p": ["Una barra de navegación suele ser una lista con display: flex.", "Las viñetas se quitan con list-style: none.", "justify-content separa el logo de los enlaces."], "c": "<style>\n  nav { display: flex; justify-content: space-between; align-items: center; background: #1e293b; padding: 10px 20px; }\n  nav ul { display: flex; gap: 16px; list-style: none; margin: 0; padding: 0; }\n  nav a, nav b { color: white; text-decoration: none; }\n</style>\n<nav><b>MiLogo</b><ul><li><a href=\"#\">Inicio</a></li><li><a href=\"#\">Cursos</a></li></ul></nav>", "h": "Construye una barra con el logo a la izquierda y los enlaces a la derecha.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que quita las viñetas de una lista es list-style: ___. (4 letras)", "e": "Olvidar quitar las viñetas y el margen de la lista."},
  {"m": "Flexbox y Grid", "t": "Grid", "x": "Sistema de CSS para organizar elementos en filas y columnas.\n\nCon display: grid el contenedor se convierte en una cuadrícula. A diferencia de flexbox, que trabaja en una dirección, grid controla filas y columnas a la vez. Es ideal para el diseño general de una página o galerías.", "u": "Crear diseños en dos dimensiones.\n\nQuieres organizar elementos en una cuadrícula de filas y columnas.", "p": ["Grid se activa con display: grid en el contenedor.", "Grid organiza elementos en filas y columnas a la vez.", "Flexbox es de una dimensión y grid de dos."], "c": "<style>\n  .cuadricula { display: grid; grid-template-columns: 100px 100px 100px; gap: 8px; }\n  .cuadricula div { background: #6ee7b7; padding: 16px; text-align: center; }\n</style>\n<div class=\"cuadricula\"><div>1</div><div>2</div><div>3</div><div>4</div><div>5</div><div>6</div></div>", "h": "Coloca seis elementos en una cuadrícula de tres columnas.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Grid se activa con display: ___. (4 letras)", "e": "Usar grid cuando bastaba flexbox, o viceversa."},
  {"m": "Flexbox y Grid", "t": "Columnas de grid", "x": "Propiedad que define las columnas de la cuadrícula.\n\ngrid-template-columns: 200px 1fr 1fr crea tres columnas: una fija y dos que se reparten el resto. La función repeat() evita repetir: repeat(3, 1fr) son tres columnas iguales. Los elementos se colocan solos por filas.", "u": "Decidir cuántas columnas hay y qué ancho tienen.\n\nQuieres una cuadrícula de tres columnas iguales sin repetir valores.", "p": ["grid-template-columns define las columnas de la cuadrícula.", "repeat(3, 1fr) crea tres columnas iguales.", "Los elementos se colocan automáticamente en las celdas."], "c": "<style>\n  .tres { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }\n  .tres div { background: #fcd34d; padding: 20px; text-align: center; }\n</style>\n<div class=\"tres\"><div>1</div><div>2</div><div>3</div><div>4</div><div>5</div></div>", "h": "Crea tres columnas iguales con la función repeat.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que define las columnas es grid-template-___. (7 letras)", "e": "Olvidar repeat y escribir mal el número de columnas."},
  {"m": "Flexbox y Grid", "t": "Unidad fr", "x": "Unidad que reparte el espacio libre en fracciones.\n\n1fr significa una fracción del espacio libre. 1fr 2fr reparte un tercio y dos tercios. Se puede mezclar con medidas fijas: 200px 1fr deja 200 px a la primera y todo lo demás a la segunda.", "u": "Repartir el ancho disponible entre columnas de grid.\n\nQuieres una columna lateral de 200 px y otra que ocupe todo el resto.", "p": ["La unidad fr reparte el espacio libre en fracciones.", "2fr recibe el doble de espacio que 1fr.", "Se puede combinar fr con medidas fijas como px."], "c": "<style>\n  .pagina { display: grid; grid-template-columns: 200px 1fr; gap: 10px; }\n  .menu { background: #fca5a5; padding: 12px; }\n  .contenido { background: #bbf7d0; padding: 12px; }\n</style>\n<div class=\"pagina\"><div class=\"menu\">Menú 200px</div><div class=\"contenido\">Contenido: ocupa el resto</div></div>", "h": "Fija un menú de 200 píxeles y deja que el contenido ocupe lo que sobra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La unidad que reparte el espacio libre en fracciones es ___. (2 letras)", "e": "Creer que fr es una unidad fija como px."},
  {"m": "Flexbox y Grid", "t": "Filas de grid", "x": "Propiedad que define el alto de las filas de la cuadrícula.\n\ngrid-template-rows funciona como las columnas pero en vertical. Si no la defines, las filas se crean solas con la altura de su contenido; grid-auto-rows permite fijar la altura de las filas automáticas.", "u": "Controlar la altura de cada fila.\n\nQuieres que la primera fila mida 80 px y la segunda se adapte al resto.", "p": ["grid-template-rows define la altura de las filas.", "Sin definirla, las filas se crean según su contenido.", "grid-auto-rows fija la altura de las filas automáticas."], "c": "<style>\n  .rejilla { display: grid; grid-template-rows: 80px 1fr; height: 200px; gap: 8px; }\n  .rejilla div { background: #a5f3fc; padding: 10px; }\n</style>\n<div class=\"rejilla\"><div>Fila de 80px</div><div>Ocupa el resto</div></div>", "h": "Define una fila fija de 80 píxeles y otra que ocupa el resto de la altura.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que define el alto de las filas es grid-template-___. (4 letras)", "e": "Olvidar dar altura al contenedor al usar fr en las filas."},
  {"m": "Flexbox y Grid", "t": "Espacios en grid", "x": "Uso de gap para separar celdas de la cuadrícula.\n\nEn grid, gap: 10px 20px da 10 px entre filas y 20 px entre columnas. Si pones un solo valor se aplica a ambos. No añade espacio en los bordes exteriores, de modo que la cuadrícula queda alineada con el contenedor.", "u": "Dejar espacio uniforme entre filas y columnas.\n\nQuieres 10 px entre filas y 30 px entre columnas de una cuadrícula.", "p": ["En grid, gap separa filas y columnas.", "Con dos valores, el primero es entre filas y el segundo entre columnas.", "El gap no añade espacio en los bordes exteriores."], "c": "<style>\n  .g { display: grid; grid-template-columns: repeat(3, 80px); gap: 10px 30px; }  /* filas | columnas */\n  .g div { background: #c4b5fd; padding: 12px; text-align: center; }\n</style>\n<div class=\"g\"><div>1</div><div>2</div><div>3</div><div>4</div><div>5</div><div>6</div></div>", "h": "Separa 10 píxeles entre filas y 30 entre columnas de una cuadrícula.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Con gap: 10px 30px, el primer valor es entre ___. (5 letras)", "e": "Confundir el orden de los dos valores de gap."},
  {"m": "Flexbox y Grid", "t": "Grid-column y grid-row", "x": "Propiedades que hacen que un elemento ocupe varias celdas.\n\ngrid-column: span 2 hace que el elemento ocupe dos columnas, y grid-row: span 2 dos filas. También se puede indicar la posición con líneas: grid-column: 1 / 3. Las líneas de la cuadrícula se numeran desde 1.", "u": "Crear elementos destacados que abarcan filas o columnas.\n\nQuieres que una tarjeta destacada ocupe dos columnas de la cuadrícula.", "p": ["grid-column: span 2 ocupa dos columnas.", "Las líneas de la cuadrícula se numeran desde 1.", "grid-row: span 2 ocupa dos filas."], "c": "<style>\n  .g { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }\n  .g div { background: #fda4af; padding: 14px; text-align: center; }\n  .g .ancha { grid-column: span 2; background: #fb7185; }\n</style>\n<div class=\"g\"><div class=\"ancha\">Ocupa 2 columnas</div><div>2</div><div>3</div><div>4</div><div>5</div></div>", "h": "Hace que un elemento destacado ocupe dos columnas de la cuadrícula.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Para ocupar dos columnas se escribe grid-column: ___ 2. (4 letras)", "e": "Empezar a contar las líneas desde cero."},
  {"m": "Flexbox y Grid", "t": "Áreas de grid", "x": "Forma de dibujar el diseño con nombres de zonas.\n\nCon grid-template-areas escribes el diseño como un dibujo con palabras, y a cada elemento le das un nombre con grid-area. Es muy legible para diseños típicos: cabecera, menú, contenido y pie.", "u": "Definir el diseño de una página de forma visual.\n\nQuieres describir el diseño de la página (cabecera, menú, contenido y pie) como un dibujo con nombres.", "p": ["grid-template-areas dibuja el diseño con nombres.", "grid-area asigna un nombre de zona a cada elemento.", "Es ideal para el diseño general de una página."], "c": "<style>\n  .pagina { display: grid; gap: 6px; grid-template-columns: 100px 1fr;\n    grid-template-areas: \"cab cab\" \"menu cont\" \"pie pie\"; }\n  .cab { grid-area: cab; background: #93c5fd; } .menu { grid-area: menu; background: #fca5a5; }\n  .cont { grid-area: cont; background: #86efac; } .pie { grid-area: pie; background: #fde68a; }\n  .pagina div { padding: 12px; }\n</style>\n<div class=\"pagina\"><div class=\"cab\">Cabecera</div><div class=\"menu\">Menú</div><div class=\"cont\">Contenido</div><div class=\"pie\">Pie</div></div>", "h": "Dibuja con nombres un diseño con cabecera, menú, contenido y pie.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que dibuja el diseño con nombres es grid-template-___. (5 letras)", "e": "Escribir un área con forma que no es rectangular."},
  {"m": "Flexbox y Grid", "t": "Auto-fit y minmax", "x": "Funciones que crean columnas adaptables sin media queries.\n\nrepeat(auto-fit, minmax(200px, 1fr)) crea tantas columnas de al menos 200 px como quepan, y se estiran para llenar el espacio. Cuando se estrecha la pantalla, las columnas bajan solas. Es el truco clave para tarjetas responsive.", "u": "Hacer galerías que se reorganizan según el ancho disponible.\n\nQuieres una galería que muestre más o menos columnas según el ancho de pantalla sin escribir media queries.", "p": ["minmax define un tamaño mínimo y uno máximo.", "auto-fit crea tantas columnas como quepan.", "Permite diseños adaptables sin usar media queries."], "c": "<style>\n  .galeria { display: grid; gap: 10px;\n    grid-template-columns: repeat(auto-fit, minmax(110px, 1fr)); }\n  .galeria div { background: #67e8f9; padding: 24px; text-align: center; }\n</style>\n<div class=\"galeria\"><div>1</div><div>2</div><div>3</div><div>4</div><div>5</div><div>6</div></div>", "h": "Crea una galería cuyas columnas se adaptan al ancho disponible.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que define un tamaño mínimo y máximo es ___(). (6 letras)", "e": "Usar un mínimo mayor que el ancho de pantallas pequeñas."},
  {"m": "Responsive y efectos", "t": "Media queries", "x": "Reglas que se aplican solo si se cumple una condición de pantalla.\n\nSe escriben con @media y una condición: @media (max-width: 600px) { ... } aplica lo de dentro solo si la ventana mide 600 px o menos. Es la herramienta principal del diseño responsive.", "u": "Cambiar el diseño según el ancho o el tipo de pantalla.\n\nQuieres que, en pantallas estrechas, tres columnas pasen a ser una sola.", "p": ["Una media query aplica estilos solo cuando se cumple su condición.", "@media (max-width: 600px) actúa en pantallas de 600 px o menos.", "Las media queries son la base del diseño responsive."], "c": "<style>\n  .fila { display: flex; gap: 8px; }\n  .fila div { flex: 1; background: #fbbf24; padding: 16px; }\n  /* si la ventana mide 500px o menos, se apilan */\n  @media (max-width: 500px) { .fila { flex-direction: column; } }\n</style>\n<div class=\"fila\"><div>1</div><div>2</div><div>3</div></div>", "h": "Apila las columnas cuando la ventana es estrecha.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Las media queries se escriben con @___. (5 letras)", "e": "Olvidar la etiqueta meta viewport y que no funcionen en el móvil. Faltan los dos puntos: max-width: 600px."},
  {"m": "Responsive y efectos", "t": "Puntos de corte", "x": "Anchos de pantalla en los que cambia el diseño.\n\nValores típicos: 600 px para móviles grandes, 900 px para tabletas y 1200 px para escritorio. No es obligatorio usar esos números: pon el punto de corte donde tu diseño se rompe. Menos puntos de corte significa un CSS más simple.", "u": "Decidir cuándo adaptar el diseño.\n\nQuieres decidir a qué ancho de pantalla tu diseño pasa de móvil a tableta.", "p": ["Un punto de corte es el ancho donde cambia el diseño.", "Valores comunes son 600, 900 y 1200 píxeles.", "Es mejor poner el corte donde el diseño empieza a fallar."], "c": "<style>\n  body { background: #dbeafe; }\n  @media (min-width: 600px)  { body { background: #bbf7d0; } }   /* tableta */\n  @media (min-width: 1000px) { body { background: #fde68a; } }   /* escritorio */\n</style>\n<p>Cambia el tamaño de la ventana para ver el color del fondo cambiar.</p>", "h": "Cambia el color de fondo en tres anchos de pantalla distintos.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un ancho de pantalla donde cambia el diseño es un punto de ___. (5 letras)", "e": "Usar demasiados puntos de corte."},
  {"m": "Responsive y efectos", "t": "Mobile first", "x": "Enfoque que diseña primero para móvil y amplía después.\n\nEscribes los estilos base pensando en el móvil y usas min-width para añadir mejoras en pantallas mayores. El CSS queda más corto, porque el móvil no tiene que «deshacer» nada, y obliga a priorizar el contenido.", "u": "Empezar por lo esencial y mejorar para pantallas grandes.\n\nQuieres diseñar primero la versión móvil y añadir mejoras solo en pantallas grandes.", "p": ["Mobile first empieza diseñando para pantallas pequeñas.", "Se amplía el diseño con media queries de min-width.", "Obliga a decidir qué contenido es lo más importante."], "c": "<style>\n  /* Base (móvil): una columna */\n  .rejilla { display: grid; gap: 8px; }\n  .rejilla div { background: #a7f3d0; padding: 16px; }\n  /* Pantallas grandes: tres columnas */\n  @media (min-width: 700px) { .rejilla { grid-template-columns: repeat(3, 1fr); } }\n</style>\n<div class=\"rejilla\"><div>1</div><div>2</div><div>3</div></div>", "h": "Empieza con una columna y pasa a tres solo en pantallas grandes.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En mobile first, las mejoras se añaden con ___-width. (3 letras)", "e": "Diseñar para escritorio y luego intentar encoger todo."},
  {"m": "Responsive y efectos", "t": "Imágenes adaptables", "x": "Técnicas para que las imágenes se ajusten sin deformarse.\n\nmax-width: 100% y height: auto evitan que una imagen se salga. Con object-fit: cover la imagen llena la caja recortando lo que sobre, y con contain se ve entera dejando bordes. Así las fotos no se estiran.", "u": "Mostrar fotos bien en cualquier tamaño de caja.\n\nQuieres que una foto llene una caja sin estirarse, aunque se recorte un poco.", "p": ["max-width: 100% evita que una imagen se salga de su contenedor.", "object-fit: cover recorta la imagen para llenar la caja.", "height: auto mantiene la proporción de la imagen."], "c": "<style>\n  .marco { width: 200px; height: 120px; border: 2px solid gray; }\n  .marco img { width: 100%; height: 100%; object-fit: cover; }  /* llena la caja sin deformar */\n</style>\n<div class=\"marco\"><img src=\"https://picsum.photos/400/300\" alt=\"Foto de ejemplo\"></div>", "h": "Llena un marco con una imagen recortándola en vez de estirarla.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor de object-fit que llena la caja recortando es ___. (5 letras)", "e": "Dar ancho y alto fijos a una imagen y deformarla."},
  {"m": "Responsive y efectos", "t": "Clamp", "x": "Función que limita un valor entre un mínimo y un máximo.\n\nclamp(1rem, 4vw, 2rem) elige el valor central pero nunca baja de 1rem ni sube de 2rem. Es perfecta para tipografía fluida: el título crece con la pantalla dentro de unos límites razonables.", "u": "Crear tamaños fluidos que se adaptan sin saltos.\n\nQuieres un título que crezca con la pantalla pero sin ser nunca ni diminuto ni gigante.", "p": ["clamp recibe mínimo, valor ideal y máximo.", "El resultado nunca baja del mínimo ni supera el máximo.", "Es ideal para tipografía que crece con la pantalla."], "c": "<style>\n  h1 {\n    /*      mínimo  ideal  máximo */\n    font-size: clamp(1.5rem, 6vw, 3rem);\n  }\n</style>\n<h1>Título fluido: cambia el ancho de la ventana</h1>", "h": "Hace que el título crezca con la ventana dentro de unos límites.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función con mínimo, ideal y máximo es ___(). (5 letras)", "e": "Olvidar el orden mínimo, ideal y máximo."},
  {"m": "Responsive y efectos", "t": "Variables CSS", "x": "Valores con nombre que se definen una vez y se reutilizan.\n\nSe definen con dos guiones, por ejemplo --azul: #2563eb;, normalmente en :root. Se usan con var(--azul). Si cambias el valor en un solo sitio, todo el sitio se actualiza, lo que facilita crear temas.", "u": "Cambiar colores y medidas de todo el sitio en un solo lugar.\n\nQuieres cambiar el color principal de todo el sitio modificando un único valor.", "p": ["Las variables CSS se definen con dos guiones delante.", "Se usan con la función var().", "Suelen declararse dentro de :root."], "c": "<style>\n  :root { --principal: #7c3aed; --radio: 12px; }       /* se define una vez */\n  .boton { background: var(--principal); border-radius: var(--radio); color: white; padding: 8px 16px; border: 0; }\n  h1 { color: var(--principal); }\n</style>\n<h1>Con variables</h1><button class=\"boton\">Botón</button>", "h": "Reutiliza un color y un radio definidos una sola vez.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una variable CSS empieza con ___ guiones. (un número)", "e": "Olvidar var() y escribir solo el nombre de la variable. Para usar la variable se escribe var(--color), no solo --color."},
  {"m": "Responsive y efectos", "t": "Modo oscuro", "x": "Tema oscuro activado por la preferencia del sistema.\n\nLa media query @media (prefers-color-scheme: dark) detecta si el sistema está en modo oscuro. Con variables CSS basta con redefinirlas dentro de ella. Cuida que el contraste del texto siga siendo suficiente.", "u": "Respetar si la persona prefiere pantallas oscuras.\n\nQuieres que tu página use colores oscuros si el dispositivo está en modo oscuro.", "p": ["prefers-color-scheme detecta el tema del sistema.", "Con variables basta redefinirlas para el modo oscuro.", "En modo oscuro hay que revisar el contraste."], "c": "<style>\n  :root { --fondo: #ffffff; --texto: #0f172a; }\n  @media (prefers-color-scheme: dark) { :root { --fondo: #0f172a; --texto: #e2e8f0; } }\n  body { background: var(--fondo); color: var(--texto); padding: 16px; }\n</style>\n<p>Cambia el tema de tu sistema y mira qué pasa.</p>", "h": "Cambia el fondo y el texto según el modo claro u oscuro del sistema.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La media query del tema se escribe prefers-color-___. (6 letras)", "e": "Olvidar revisar el contraste en modo oscuro."},
  {"m": "Responsive y efectos", "t": "Función calc", "x": "Función que hace operaciones con medidas distintas.\n\ncalc(100% - 200px) resta 200 píxeles al ancho del padre, algo que no se puede hacer con un número fijo. Los operadores + y - necesitan espacio a ambos lados, y se pueden mezclar unidades distintas.", "u": "Mezclar unidades como % y px en un mismo valor.\n\nQuieres que una caja ocupe todo el ancho menos 200 píxeles.", "p": ["calc permite operar con unidades distintas.", "Los operadores + y - necesitan espacios a ambos lados.", "calc(100% - 200px) resta 200 px al ancho disponible."], "c": "<style>\n  .contenido { width: calc(100% - 200px); background: #bfdbfe; padding: 10px; }\n  .caja { height: calc(50px + 2rem); background: #fecdd3; }\n</style>\n<div class=\"contenido\">Ancho: 100% - 200px</div>\n<div class=\"caja\">Alto: 50px + 2rem</div>", "h": "Calcula medidas mezclando porcentajes, píxeles y rem.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función que hace operaciones con medidas es ___(). (4 letras)", "e": "Escribir calc(100%-200px) sin espacios."},
  {"m": "Responsive y efectos", "t": "Transition", "x": "Propiedad que anima un cambio de estilo de forma suave.\n\ntransition: background 0.3s ease; indica qué propiedad cambia, cuánto tarda y cómo acelera. Se escribe en el estado normal del elemento, no en :hover. Animar solo color, opacidad y transform es lo más fluido.", "u": "Hacer que hover y otros cambios no sean bruscos.\n\nQuieres que el cambio de color de un botón al pasar el mouse sea gradual.", "p": ["transition suaviza el paso de un estilo a otro.", "Se escribe en el estado normal del elemento.", "Lleva la propiedad, la duración y el tipo de aceleración."], "c": "<style>\n  .boton { background: tomato; color: white; padding: 10px 20px; border: 0;\n           transition: background 0.4s ease, transform 0.2s; }   /* en el estado normal */\n  .boton:hover { background: darkred; transform: scale(1.1); }\n</style>\n<button class=\"boton\">Pasa el mouse</button>", "h": "Anima suavemente el color y el tamaño de un botón al pasar el mouse.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que suaviza un cambio de estilo es ___. (10 letras)", "e": "Escribir transition dentro de :hover en lugar del estado normal."},
  {"m": "Responsive y efectos", "t": "Transform", "x": "Propiedad que mueve, gira, escala o inclina un elemento.\n\ntranslate(x, y) mueve, rotate(45deg) gira, scale(1.5) agranda y skew inclina. No modifican el espacio que ocupa el elemento en el flujo y son muy eficientes de animar. Se pueden combinar separándolas con espacios.", "u": "Cambiar la forma o posición visual sin alterar el diseño.\n\nQuieres girar una tarjeta 10 grados sin afectar a los demás elementos.", "p": ["transform puede mover, girar, escalar e inclinar.", "No cambia el espacio que el elemento ocupa en el flujo.", "Se pueden combinar varias transformaciones en una."], "c": "<style>\n  .caja { width: 80px; padding: 20px; margin: 30px; background: #fde68a; text-align: center; }\n  .gira   { transform: rotate(15deg); }\n  .grande { transform: scale(1.3); }\n  .mueve  { transform: translate(40px, 10px); }\n</style>\n<div class=\"caja gira\">Gira</div><div class=\"caja grande\">Escala</div><div class=\"caja mueve\">Mueve</div>", "h": "Gira, agranda y mueve tres cajas sin cambiar el flujo de la página.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La función de transform que gira es ___(). (6 letras)", "e": "Creer que transform empuja a los demás elementos."},
  {"m": "Responsive y efectos", "t": "Animation y keyframes", "x": "Forma de crear animaciones que se repiten con pasos propios.\n\nPrimero defines los pasos con @keyframes nombre { from {...} to {...} } y luego los aplicas con animation: nombre 2s infinite;. A diferencia de transition, la animación puede empezar sola y repetirse. Respeta a quienes prefieren menos movimiento.", "u": "Animar elementos sin esperar a que el usuario haga algo.\n\nQuieres un icono que lata sin parar sin que nadie lo toque.", "p": ["@keyframes define los pasos de una animación.", "La propiedad animation aplica los keyframes a un elemento.", "Una animación puede repetirse con infinite."], "c": "<style>\n  @keyframes latido { 0% { transform: scale(1); } 50% { transform: scale(1.3); } 100% { transform: scale(1); } }\n  .corazon { font-size: 40px; width: 50px; animation: latido 1s infinite; }\n  @media (prefers-reduced-motion: reduce) { .corazon { animation: none; } }\n</style>\n<div class=\"corazon\">❤️</div>", "h": "Hace latir un corazón de forma continua y respeta a quien reduce el movimiento.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Los pasos de una animación se definen con @___. (9 letras)", "e": "Olvidar dar nombre a los keyframes o escribirlo distinto."},
  {"m": "Responsive y efectos", "t": "Gradientes", "x": "Fondos que mezclan dos o más colores de forma progresiva.\n\nlinear-gradient(90deg, rojo, azul) mezcla colores en línea recta con el ángulo que indiques. radial-gradient lo hace desde un punto central. Se usan en background (no en background-color) y pesan mucho menos que una imagen.", "u": "Crear fondos vistosos sin necesidad de imágenes.\n\nQuieres un fondo que pase del azul al violeta sin usar una imagen.", "p": ["linear-gradient mezcla colores en línea recta.", "radial-gradient mezcla colores desde un centro.", "Los gradientes se escriben en background, no en background-color."], "c": "<style>\n  .a { background: linear-gradient(90deg, #38bdf8, #8b5cf6); height: 60px; }\n  .b { background: radial-gradient(circle, #fde68a, #f97316); height: 60px; }\n</style>\n<div class=\"a\"></div><div class=\"b\"></div>", "h": "Pinta una franja con degradado lineal y otra con degradado radial.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El degradado en línea recta se escribe ___-gradient. (6 letras)", "e": "Escribir el gradiente en background-color."},
  {"m": "Responsive y efectos", "t": "Opacidad y transparencia", "x": "Formas de hacer un elemento o color parcialmente transparente.\n\nopacity: 0.5 hace transparente todo el elemento, incluido su texto. rgba(0, 0, 0, 0.5) o hsla aplican transparencia solo al color, dejando el texto normal. Usa opacity para atenuar e rgba para fondos translúcidos.", "u": "Crear capas translúcidas y atenuar elementos.\n\nQuieres un fondo negro semitransparente que no atenúe el texto de encima.", "p": ["opacity afecta a todo el elemento, incluido su texto.", "rgba aplica transparencia solo al color indicado.", "opacity: 0 hace invisible el elemento."], "c": "<style>\n  .fondo { background: url(https://picsum.photos/400/150); padding: 30px; }\n  .a { background: rgba(0, 0, 0, 0.6); color: white; padding: 10px; }   /* solo el fondo es translúcido */\n  .b { opacity: 0.5; background: black; color: white; padding: 10px; }   /* todo es translúcido */\n</style>\n<div class=\"fondo\"><div class=\"a\">rgba: texto nítido</div><br><div class=\"b\">opacity: texto tenue</div></div>", "h": "Compara un fondo translúcido con rgba y otro con opacity.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que hace transparente todo un elemento es ___. (7 letras)", "e": "Usar opacity y atenuar también el texto sin querer."},
  {"m": "Responsive y efectos", "t": "Filtros", "x": "Efectos visuales como desenfoque y brillo aplicados con CSS.\n\nfilter: blur(4px) desenfoca, grayscale(100%) pasa a blanco y negro y brightness(1.2) aclara. backdrop-filter aplica el efecto a lo que hay detrás del elemento, como un cristal esmerilado.", "u": "Retocar imágenes y fondos sin editor.\n\nQuieres que una foto se vea en blanco y negro sin editarla.", "p": ["filter aplica efectos como blur y grayscale.", "backdrop-filter afecta a lo que hay detrás del elemento.", "Los filtros se pueden combinar separándolos con espacios."], "c": "<style>\n  .foto { width: 160px; height: 100px; object-fit: cover; }\n  .bn     { filter: grayscale(100%); }\n  .borrosa { filter: blur(3px); }\n  .brillo  { filter: brightness(1.3) saturate(1.5); }\n</style>\n<img class=\"foto bn\" src=\"https://picsum.photos/200/120\" alt=\"Blanco y negro\">\n<img class=\"foto borrosa\" src=\"https://picsum.photos/200/120\" alt=\"Borrosa\">\n<img class=\"foto brillo\" src=\"https://picsum.photos/200/120\" alt=\"Brillante\">", "h": "Aplica blanco y negro, desenfoque y más brillo a tres imágenes.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que aplica efectos visuales es ___. (6 letras)", "e": "Usar filtros pesados en muchas imágenes y ralentizar la página."},
  {"m": "Responsive y efectos", "t": "Cursor", "x": "Propiedad que cambia el puntero del mouse.\n\ncursor: pointer muestra la mano en elementos pulsables que no son enlaces. Otros valores: not-allowed (prohibido), text, grab y wait. Un cursor coherente ayuda a entender la interfaz.", "u": "Indicar qué elementos se pueden pulsar.\n\nQuieres que el puntero se convierta en una mano al pasar sobre una tarjeta pulsable.", "p": ["cursor: pointer muestra la mano sobre elementos pulsables.", "cursor: not-allowed indica que una acción no está permitida.", "Un cursor coherente ayuda a entender la interfaz."], "c": "<style>\n  .tarjeta { padding: 14px; background: #e0f2fe; margin: 6px; cursor: pointer; }\n  .bloqueado { padding: 14px; background: #e5e7eb; margin: 6px; cursor: not-allowed; opacity: .6; }\n</style>\n<div class=\"tarjeta\">Pulsable (mano)</div>\n<div class=\"bloqueado\">No disponible (prohibido)</div>", "h": "Muestra una mano en una tarjeta pulsable y un cursor de prohibido en otra.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: El valor de cursor que muestra la mano es ___. (7 letras)", "e": "Dejar el cursor normal en elementos pulsables."},
  {"m": "Responsive y efectos", "t": "Fuentes web", "x": "Tipos de letra cargados desde internet.\n\nServicios como Google Fonts ofrecen cientos de fuentes: añades un link en el head y usas el nombre en font-family. También existe @font-face para cargar un archivo propio. Cada fuente añade peso a la página, así que usa pocas.", "u": "Usar una tipografía que no está instalada en el dispositivo.\n\nQuieres usar una tipografía especial que los visitantes no tienen instalada.", "p": ["Las fuentes web se descargan desde internet.", "Google Fonts se enlaza desde el head de la página.", "Cada fuente adicional hace más pesada la página."], "c": "<link href=\"https://fonts.googleapis.com/css2?family=Pacifico&display=swap\" rel=\"stylesheet\">\n<style>\n  /* si la fuente no carga, usa cursive */\n  h1 { font-family: \"Pacifico\", cursive; font-size: 2.2rem; }\n</style>\n<h1>Mi tipografía especial</h1>", "h": "Carga una fuente de Google Fonts y la aplica a un título.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La regla para cargar una fuente propia es @font-___. (4 letras)", "e": "Cargar muchas fuentes y ralentizar la página."},
  {"m": "Responsive y efectos", "t": "Aspect-ratio", "x": "Propiedad que fija la proporción entre ancho y alto.\n\naspect-ratio: 16 / 9 hace que la altura siga siendo proporcional al ancho. Es ideal para videos, tarjetas e imágenes: reservas el espacio antes de que cargue el contenido y evitas saltos en la página.", "u": "Mantener cajas o videos con forma constante.\n\nQuieres que una caja mantenga forma de pantalla panorámica 16 a 9 al cambiar de ancho.", "p": ["aspect-ratio mantiene una proporción entre ancho y alto.", "16 / 9 es una proporción típica de video.", "Evita saltos mientras el contenido carga."], "c": "<style>\n  .video { width: 100%; max-width: 320px; aspect-ratio: 16 / 9; background: #1e293b; color: white;\n           display: grid; place-items: center; }\n  .cuadrado { width: 100px; aspect-ratio: 1; background: #fb923c; }\n</style>\n<div class=\"video\">16 / 9</div><div class=\"cuadrado\"></div>", "h": "Mantiene una caja en proporción 16 a 9 y otra siempre cuadrada.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: La propiedad que fija la proporción de una caja es aspect-___. (5 letras)", "e": "Fijar ancho y alto en píxeles y perder la proporción al redimensionar."},
  {"m": "Responsive y efectos", "t": "Reset de estilos", "x": "Conjunto de reglas que eliminan diferencias entre navegadores.\n\nCada navegador tiene márgenes y tamaños por defecto distintos. Un reset sencillo pone margin y padding en cero y box-sizing en border-box para todo. Algunas librerías como Normalize.css lo hacen con más cuidado.", "u": "Partir de una base igual en todos los navegadores.\n\nQuieres que tu página se vea igual en todos los navegadores desde la primera regla.", "p": ["Un reset elimina las diferencias entre navegadores.", "Un reset básico pone margin y padding en cero.", "Normalize.css es una alternativa más suave."], "c": "<style>\n  /* Reset básico al principio del archivo */\n  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n  body { font-family: system-ui, sans-serif; line-height: 1.5; }\n  img { max-width: 100%; display: block; }\n</style>\n<h1>Con reset</h1><p>Todo parte del mismo punto.</p>", "h": "Aplica un reset básico para que todos los navegadores partan igual.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Un reset básico pone margin y padding en ___. (4 letras)", "e": "Olvidar volver a poner márgenes tras un reset."},
  {"m": "Responsive y efectos", "t": "Metodología BEM", "x": "Convención para nombrar clases con bloque, elemento y modificador.\n\nBEM nombra las clases así: bloque (.tarjeta), elemento (.tarjeta__titulo) y modificador (.tarjeta--destacada). Los nombres cuentan qué es cada cosa y a quién pertenece, y evitan choques entre clases de distintos componentes.", "u": "Mantener ordenado el CSS de proyectos grandes.\n\nQuieres nombrar las clases de un componente para que nunca choquen con otras.", "p": ["BEM significa Bloque, Elemento y Modificador.", "Los elementos se escriben con doble guion bajo.", "Los modificadores se escriben con doble guion medio."], "c": "<style>\n  .tarjeta { border: 2px solid #94a3b8; padding: 12px; width: 220px; }\n  .tarjeta__titulo { font-size: 1.2rem; margin: 0 0 6px; }\n  .tarjeta--destacada { border-color: gold; background: #fef9c3; }\n</style>\n<div class=\"tarjeta tarjeta--destacada\"><h3 class=\"tarjeta__titulo\">Oferta</h3>Texto de la tarjeta</div>", "h": "Nombra una tarjeta, su título y una variante destacada con BEM.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: En BEM, «tarjeta» es el ___. (6 letras)", "e": "Mezclar estilos de nombres sin una convención."},
  {"m": "Responsive y efectos", "t": "Proyecto landing responsive", "x": "Página de presentación completa que se adapta a cualquier pantalla.\n\nPara cerrar CSS, crea una landing page: cabecera con menú flex, portada con degradado, rejilla de tarjetas con auto-fit, variables para los colores y hover con transition. Revísala en móvil, tableta y escritorio con el inspector.", "u": "Practicar todo lo aprendido en un proyecto real.\n\nQuieres cerrar el curso con un proyecto que reúna flexbox, grid, variables y diseño adaptable.", "p": ["Una landing page presenta un producto o servicio en una sola página.", "Un buen proyecto final combina flexbox, grid, variables y responsive.", "Hay que probarla en varios tamaños de pantalla."], "c": "<style>\n  :root { --color: #6366f1; }\n  * { box-sizing: border-box; margin: 0; }\n  body { font-family: system-ui, sans-serif; }\n  nav { display: flex; justify-content: space-between; padding: 12px 20px; background: var(--color); color: white; }\n  .portada { background: linear-gradient(135deg, var(--color), #ec4899); color: white; padding: 40px 20px; text-align: center; }\n  .rejilla { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; padding: 16px; }\n  .tarjeta { background: #eef2ff; padding: 16px; border-radius: 12px; transition: transform .2s; }\n  .tarjeta:hover { transform: translateY(-4px); }\n</style>\n<nav><b>MiMarca</b><span>Menú</span></nav>\n<section class=\"portada\"><h1>Aprende CSS</h1><p>Diseño adaptable y moderno</p></section>\n<div class=\"rejilla\"><div class=\"tarjeta\">Rápido</div><div class=\"tarjeta\">Fácil</div><div class=\"tarjeta\">Responsive</div></div>", "h": "Une menú flex, portada con degradado y tarjetas adaptables con variables.", "r": "Cambia el código del ejemplo y mira qué pasa. Reto: Una página de presentación de un producto se llama landing ___. (4 letras)", "e": "No probar el proyecto en pantallas pequeñas."}
];
